-- A third batch of original Logical Reasoning MCQs for Markhor Prep, written against the PMDC MDCAT 2025 curriculum
-- (Logical Reasoning themes 5.1 to 5.6). LR-0217 to LR-0490 (274 questions), following on from migration 0030.
-- 70 fill syllabus gaps the earlier batches covered thinly or not at all (geometric progressions, symbol series,
-- mathematical operations, data sufficiency, building on given structures, linked problems, strong and weak arguments,
-- gathering information, positive reasoning); 204 are difficult questions spread across all six chapters.
-- Not taken from any book. Each question's source names the learning outcome it tests. Not in the free set.
--
-- Logical Reasoning is only on the national MDCAT (NUMS and AKU papers have no LR section), so it gets no bank_questions rows.
-- INSERT OR IGNORE keeps the file safe to run twice; if the site owner's admin account doesn't exist (a fresh local database)
-- nothing is inserted. Inserted in batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0217', 'Logical Reasoning', 'Critical thinking', 'Valid and invalid arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', '"If a number is divisible by 6, it is divisible by 3. The number 21 is divisible by 3. So 21 is divisible by 6."
Which statement about this argument is correct?', '["It is valid because both premises are true", "It is valid because 21 is an odd number", "It is invalid because 21 is not divisible by 3", "It is invalid: being divisible by 3 does not guarantee being divisible by 6"]', 3, 'The argument reasons backwards from ''divisible by 3'' to ''divisible by 6'' (affirming the consequent). 21 shows the conclusion can be false.', '{"0": "True premises do not make an argument valid; the form matters, and 21 ÷ 6 is not a whole number.", "1": "Being odd is irrelevant and actually shows 21 is not divisible by 6.", "2": "21 is divisible by 3 (21 = 3 × 7)."}'),
  ('LR-0218', 'Logical Reasoning', 'Critical thinking', 'Valid and invalid arguments', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', 'Which of these arguments is logically VALID?', '["If the fuse blows, the lights go out. The lights did not go out. So the fuse did not blow.", "If the fuse blows, the lights go out. The lights went out. So the fuse blew.", "If the fuse blows, the lights go out. The fuse did not blow. So the lights did not go out.", "Some fuses blow. The lights went out. So a fuse blew."]', 0, 'This is denying the consequent (modus tollens): if the fuse had blown, the lights would be out; they are not, so it did not blow.', '{"1": "Affirming the consequent: the lights could go out for another reason.", "2": "Denying the antecedent: the lights could still go out for another reason.", "3": "The premises do not connect the lights to any fuse."}'),
  ('LR-0219', 'Logical Reasoning', 'Critical thinking', 'Valid and invalid arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', '"All surgeons are doctors. So Ayesha is a doctor."
Which added statement makes this argument valid?', '["Some doctors are surgeons", "Ayesha is a surgeon", "Ayesha works in a hospital", "Ayesha wants to be a surgeon"]', 1, 'With ''Ayesha is a surgeon'', the argument becomes: all surgeons are doctors, Ayesha is a surgeon, so Ayesha is a doctor, which is valid.', '{"0": "This does not place Ayesha in any group.", "2": "Working in a hospital does not make someone a doctor.", "3": "Wanting to be one does not make her one."}'),
  ('LR-0220', 'Logical Reasoning', 'Critical thinking', 'Valid and invalid arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', 'Claim: "Every prime number is odd."
Which single fact proves this claim false?', '["9 is an odd number that is not prime", "Most prime numbers are odd", "2 is a prime number", "1 is neither prime nor composite"]', 2, '2 is prime and even, so it is a counterexample: one case is enough to show an ''every'' claim is false.', '{"0": "An odd non-prime does not contradict ''every prime is odd''.", "1": "This supports the claim rather than refuting it.", "3": "1 is not prime, so it says nothing about primes."}'),
  ('LR-0221', 'Logical Reasoning', 'Critical thinking', 'Reasonable belief', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'Which is the BEST reason to believe that the Earth is roughly a sphere?', '["Most people believe it", "A famous person said so", "School globes are round", "Ships disappear hull-first over the horizon, and the Earth casts a round shadow on the Moon in every lunar eclipse"]', 3, 'These are observations anyone can check, and a sphere explains both. Good beliefs rest on evidence, not on popularity or authority alone.', '{"0": "Popularity is not evidence.", "1": "An authority''s word is weaker than evidence that can be checked.", "2": "Globes are made to match the belief; they are not evidence for it."}'),
  ('LR-0222', 'Logical Reasoning', 'Critical thinking', 'Reasonable belief', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'Asim believes a certain blood-pressure machine gives accurate readings. Which reason would make his belief best justified?', '["Independent tests on many machines found its readings matched hospital equipment", "Its advertisement says it is the most accurate", "His friend likes its colour", "It is the most expensive model"]', 0, 'Independent testing against a trusted standard is real evidence of accuracy.', '{"1": "An advertisement is not independent.", "2": "Colour has nothing to do with accuracy.", "3": "Price does not prove accuracy."}'),
  ('LR-0223', 'Logical Reasoning', 'Critical thinking', 'Reasonable belief', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'In large trials over many years, patients taking drug Q often showed changes in their liver tests.
Which belief is MOST reasonable on this evidence?', '["Drug Q should be banned immediately", "Patients taking drug Q should have their liver checked regularly", "Drug Q causes liver failure in everyone", "Liver changes are unrelated to drug Q"]', 1, 'The evidence shows a risk worth monitoring. It does not show that every patient is harmed or that the drug must be banned.', '{"0": "The evidence shows changes, not that the drug''s harm outweighs its benefits.", "2": "''Often'' is not ''everyone'', and ''changes'' is not ''failure''.", "3": "Large repeated trials suggest a real link."}'),
  ('LR-0224', 'Logical Reasoning', 'Critical thinking', 'True and false beliefs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', 'Which of these is a FALSE belief?', '["Vaccines help the body make antibodies", "Boiling water kills most germs", "Antibiotics cure viral infections such as the common cold", "Washing hands reduces the spread of infection"]', 2, 'Antibiotics act on bacteria, not viruses. The common cold is caused by viruses, so antibiotics do not cure it.', '{"0": "This is true: vaccines trigger antibody production.", "1": "This is true: boiling kills most disease-causing germs.", "3": "This is true and well supported by evidence."}'),
  ('LR-0225', 'Logical Reasoning', 'Critical thinking', 'True and false beliefs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', 'A student says, "I failed because my exam fell on the 13th, and 13 is an unlucky number."
Which evidence would best show this belief is false?', '["Some people are afraid of the number 13", "The student studied for only two days", "Some buildings skip the 13th floor", "Results over many years show no difference between exams held on the 13th and on other dates"]', 3, 'A large comparison showing the date makes no difference directly tests and rejects the belief.', '{"0": "Fear of 13 does not test whether it affects results.", "1": "This suggests another cause for this student but does not test the belief about 13 in general.", "2": "This shows the belief is common, not that it is true or false."}'),
  ('LR-0226', 'Logical Reasoning', 'Critical thinking', 'Parallel reasoning', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', '"All insects have six legs. Ants are insects. So ants have six legs."
Which argument has the SAME logical form?', '["All metals conduct electricity. Copper is a metal. So copper conducts electricity.", "Some birds cannot fly. Penguins are birds. So penguins cannot fly.", "All fish live in water. Frogs live in water. So frogs are fish.", "No reptile has fur. Snakes are reptiles. So snakes are not mammals."]', 0, 'Both arguments run: all A are B; X is an A; so X is B.', '{"1": "This starts with ''some'', so the form is different (and invalid).", "2": "This reasons from the B-group back to A, an invalid form.", "3": "This uses ''no'' and draws a conclusion about a third group."}'),
  ('LR-0227', 'Logical Reasoning', 'Critical thinking', 'Parallel reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"If an animal is a cat, it has whiskers. My pet has whiskers, so it is a cat."
Which argument contains the SAME flaw?', '["If it rains, the road gets wet. It rained, so the road is wet.", "If a student tops the class, she gets a prize. Hina got a prize, so she topped the class.", "If it is Friday, the bank closes early. The bank did not close early, so it is not Friday.", "All doctors studied biology. Sara is a doctor, so she studied biology."]', 1, 'Both arguments affirm the consequent: they assume the only way to get the result (whiskers, a prize) is the stated condition.', '{"0": "This is a valid argument (affirming the antecedent).", "2": "This is valid (denying the consequent).", "3": "This is a valid ''all A are B'' argument."}'),
  ('LR-0228', 'Logical Reasoning', 'Critical thinking', 'Fact and opinion', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', 'Which statement can be shown to be TRUE or FALSE by checking facts?', '["Karachi is the most exciting city in Pakistan", "Quetta has the most pleasant weather", "Karachi has a larger population than Quetta", "Living in a big city is better than living in a village"]', 2, 'Population can be counted and compared, so this statement can be checked. The others are matters of opinion.', '{"0": "''Most exciting'' is a personal opinion.", "1": "''Most pleasant'' depends on personal taste.", "3": "''Better'' is a value judgement."}'),
  ('LR-0229', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"The college should hold the final exam in the morning instead of the afternoon, because students perform better when they are fresh."
Which assumption does this argument depend on?', '["Morning exams cost the college less to run", "Students are fresher in the morning than in the afternoon", "Every student prefers waking up early", "The final exam is too long"]', 1, 'The argument links ''morning'' to ''fresh''. If students were not fresher in the morning, the reason given would not support the change at all.', '{"0": "Cost is not part of the argument.", "2": "The argument needs students to be fresher, not to like mornings; ''every student'' is also far too strong.", "3": "Exam length is never mentioned."}'),
  ('LR-0230', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"To reduce dengue in the city, the council will spray insecticide in all public parks."
The plan assumes that:', '["Dengue is spread only in public parks", "Parks are crowded in summer", "A large share of the mosquitoes that spread dengue live or breed in public parks", "Insecticide is cheaper than hospital care"]', 2, 'Spraying parks can only reduce dengue if a meaningful part of the mosquito population is found there. The plan does not need parks to be the only source.', '{"0": "''Only in parks'' is too strong; the plan works even if some mosquitoes breed elsewhere.", "1": "Crowding is not linked to the plan''s logic.", "3": "The plan is about effect, not cost."}'),
  ('LR-0231', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"Hafsa scored 95% in the academy''s mock test, so she will certainly get into a medical college."
Which assumption does this conclusion rely on?', '["Hafsa studies for many hours a day", "The mock test was harder than the real exam", "Only students who take mock tests get admission", "The mock test score reliably predicts the result of the real admission process"]', 3, 'The conclusion jumps from a mock score to admission. It only works if the mock result is a dependable guide to the real outcome.', '{"0": "Study hours are not needed for the argument.", "1": "The argument does not depend on the mock being harder; it would need it to be a fair predictor.", "2": "This is far too strong and not required."}'),
  ('LR-0232', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"We should appoint Dr Kamal as head of the research lab, because he has published more papers than any other applicant."
Which assumption underlies this recommendation?', '["The number of papers published shows how well someone would run a lab", "Dr Kamal has worked at the lab before", "The other applicants have never published anything", "Research papers are expensive to publish"]', 0, 'The only reason given is the paper count. The recommendation assumes that this count reflects ability to lead the lab.', '{"1": "Previous work at the lab is not mentioned.", "2": "The argument only says he has more papers, not that others have none.", "3": "Cost of publishing is irrelevant."}'),
  ('LR-0233', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"Since the new road opened, the journey from the village to the district hospital takes half the time, so fewer patients will now die on the way."
The argument assumes that:', '["Everyone in the village owns a car", "Long journey times were contributing to deaths on the way", "The hospital has improved its services", "The road was expensive to build"]', 1, 'A faster journey can only save lives on the way if the delay was part of the reason patients were dying.', '{"0": "The road speeds up any vehicle, including ambulances and buses, so car ownership is not needed.", "2": "Hospital services do not affect deaths that happen on the way.", "3": "The cost of the road is not relevant."}'),
  ('LR-0234', 'Logical Reasoning', 'Critical thinking', 'Assumptions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"Our pharmacy''s sales of cough syrup doubled in December, so more people in our area had coughs in December."
Which assumption is NECESSARY for this argument?', '["Cough syrup is the best treatment for a cough", "Most people in the area buy their medicine from this pharmacy", "The rise in sales was not mainly caused by something else, such as a price cut or a nearby pharmacy closing", "Coughs are always more common in winter"]', 2, 'If the extra sales came from cheaper prices or from a rival''s customers, the sales figure would say nothing about how many people had coughs. The argument needs those other explanations to be ruled out.', '{"0": "Whether syrup is the best treatment does not matter.", "1": "The argument can work even if only some people use this pharmacy.", "3": "''Always'' is too strong and is not needed."}'),
  ('LR-0235', 'Logical Reasoning', 'Critical thinking', 'Strengthening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'In a study, students who read for 20 minutes every day for a term scored higher on a vocabulary test than students who did not. The researchers concluded that daily reading improves vocabulary.
Which fact, if true, most STRENGTHENS the conclusion?', '["The readers chose their own books", "Some students in both groups disliked the test", "Reading is a popular hobby", "The two groups had the same vocabulary scores before the study began"]', 3, 'If both groups started equal, the later gap is more likely due to the reading rather than to stronger students choosing to read.', '{"0": "Book choice does not show the reading caused the gain.", "1": "Disliking the test affects both groups and says nothing about cause.", "2": "Popularity of reading is irrelevant."}'),
  ('LR-0236', 'Logical Reasoning', 'Critical thinking', 'Strengthening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'A hospital says its new hand-washing rule caused the fall in infections in its wards this year.
Which fact, if true, most STRENGTHENS this claim?', '["Infection rates did not fall at similar nearby hospitals that did not adopt the rule", "The new rule was popular with nurses", "Soap prices went up this year", "The hospital also painted its wards"]', 0, 'If similar hospitals without the rule saw no fall, other shared causes (season, a weaker germ) are less likely, pointing to the rule.', '{"1": "Popularity does not show it worked.", "2": "Soap prices do not show the rule reduced infection.", "3": "Painting is a rival explanation, which weakens rather than strengthens."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0237', 'Logical Reasoning', 'Critical thinking', 'Strengthening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"Planting trees along Mall Road lowered summer temperatures on the street."
Which fact, if true, most STRENGTHENS this claim?', '["The trees were planted by volunteers", "Streets in the same city without new trees showed no fall in temperature that summer", "Trees provide shade for birds", "Mall Road carries heavy traffic all year"]', 1, 'Comparing similar streets without trees rules out a cooler summer as the reason, so the trees are the likely cause.', '{"0": "Who planted the trees is irrelevant.", "2": "Shade for birds says nothing about street temperature.", "3": "Traffic says nothing about whether the trees cooled the street."}'),
  ('LR-0238', 'Logical Reasoning', 'Critical thinking', 'Strengthening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"The scholarship programme is the reason more girls in the district now finish school."
Which fact, if true, most STRENGTHENS this claim?', '["The scholarship is paid every month", "The district also opened two new girls'' schools", "Among girls from similar families, those who got the scholarship were far more likely to finish school than those who did not", "Many boys in the district also finish school"]', 2, 'Comparing similar girls with and without the scholarship isolates the scholarship''s effect from other changes in the district.', '{"0": "How it is paid says nothing about its effect.", "1": "New schools are a rival explanation, which weakens the claim.", "3": "Boys'' results are not about the scholarship."}'),
  ('LR-0239', 'Logical Reasoning', 'Critical thinking', 'Strengthening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', '"Switching to online classes caused lower exam results at our college this year."
Which fact, if true, most STRENGTHENS this claim?', '["The online platform was expensive", "Some teachers prefer online classes", "Exams this year were the same length as last year", "Students at the same college who chose in-person classes this year did not see lower results"]', 3, 'If students taking the same exams in person did fine, the drop is linked to the online mode rather than to a harder exam or a weaker batch.', '{"0": "Cost is not related to results.", "1": "Teachers'' preferences do not show cause.", "2": "Exam length alone does not compare the two modes."}'),
  ('LR-0240', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"Since a gym opened in our town, heart attacks have fallen, so the gym caused the fall."
Which fact, if true, most WEAKENS this argument?', '["In the same period, the town''s clinic began free blood-pressure checks and treatment for all adults", "The gym charges a monthly fee", "The gym is open seven days a week", "Heart attacks are serious"]', 0, 'Free blood-pressure treatment is another likely cause of fewer heart attacks, so the fall may not be due to the gym at all.', '{"1": "The fee does not tell us whether the gym caused the fall.", "2": "Opening hours do not offer another explanation.", "3": "This is true but irrelevant to the cause."}'),
  ('LR-0241', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"Students who spend more time in the library get higher grades, so spending time in the library raises grades."
Which fact, if true, most WEAKENS this argument?', '["The library has air-conditioning", "Students who already have high grades are the ones most likely to choose to study in the library", "The library opens at 8 am", "Some students borrow books but read at home"]', 1, 'This suggests the cause runs the other way: good students choose the library, rather than the library making them good students.', '{"0": "Air-conditioning does not challenge the cause.", "2": "Opening time is irrelevant.", "3": "This does not explain the link between library time and grades."}'),
  ('LR-0242', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"A survey of people visiting city hospitals found that 80% of them have a health problem, so 80% of the city''s people have a health problem."
What most WEAKENS this conclusion?', '["The survey was done in the summer", "The survey asked ten questions", "People who visit hospitals are much more likely to be ill than people in general", "Some hospitals are private"]', 2, 'The sample is biased: hospital visitors are not representative of the whole city, so their figure cannot be applied to everyone.', '{"0": "The season alone does not make the sample unrepresentative.", "1": "The number of questions does not affect who was sampled.", "3": "Private or public, all are hospital visitors."}'),
  ('LR-0243', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"This new cough medicine works: 70% of the patients who took it recovered within a week."
Which fact, if true, most WEAKENS the claim?', '["The medicine has a pleasant taste", "Some patients took it twice a day", "The medicine is made in Pakistan", "About 70% of patients with this kind of cough recover within a week without any medicine"]', 3, 'If 70% recover anyway, the medicine shows no benefit over doing nothing.', '{"0": "Taste does not show whether it works.", "1": "Dosing details do not weaken the claim.", "2": "Where it is made is irrelevant."}'),
  ('LR-0244', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"The new teaching method is better: the class taught with it scored 15% higher than last year''s class on the board exam."
Which fact, if true, most WEAKENS this argument?', '["This year''s board exam was much easier than last year''s", "The new method uses more group work", "The class has 40 students", "Teachers needed training for the new method"]', 0, 'An easier exam could explain the higher scores without any help from the new method.', '{"1": "Group work describes the method; it does not offer another cause.", "2": "Class size does not explain why scores rose.", "3": "Training needs do not explain the higher marks."}'),
  ('LR-0245', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"Road accidents on the main highway fell this year after speed cameras were installed, so the cameras made the road safer."
Which fact, if true, most WEAKENS this argument?', '["The cameras were made abroad", "The highway was closed for repairs for most of the year, so far fewer vehicles used it", "Drivers dislike speed cameras", "Accidents are more common at night"]', 1, 'With far less traffic, fewer accidents would be expected anyway, so the fall may not be due to the cameras.', '{"0": "Where the cameras were made is irrelevant.", "2": "Disliking cameras does not explain the fall.", "3": "This is a general fact that does not offer another cause for this year''s fall."}'),
  ('LR-0246', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"We can believe Ahmed, because he always tells the truth. We know he always tells the truth because he told us so."
What is wrong with this reasoning?', '["It attacks the author instead of the argument", "It generalises from too few examples", "It is circular: it trusts Ahmed''s own word to prove that his word can be trusted", "It offers only two options when more exist"]', 2, 'The reasoning assumes what it is trying to prove: Ahmed''s honesty is ''proved'' by taking his word as true. This is circular reasoning (begging the question).', '{"0": "No person is attacked.", "1": "No examples are used.", "3": "No choice between options is offered."}'),
  ('LR-0247', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"Dr Rehan''s research showing that smoking harms the lungs cannot be trusted, because he used to smoke himself."
This argument is an example of:', '["Circular reasoning", "A slippery slope", "Appeal to popularity", "Attacking the person instead of the evidence (ad hominem)"]', 3, 'Whether Dr Rehan smoked has no bearing on whether his research is correct. The argument attacks him rather than his evidence.', '{"0": "The argument does not assume its own conclusion.", "1": "No chain of worsening events is predicted.", "2": "It does not say the research is wrong because most people think so."}'),
  ('LR-0248', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"Either we close the college canteen completely, or students will keep eating unhealthy food forever."
What is the main flaw?', '["It presents only two options when others exist, such as offering healthier food (false dilemma)", "It attacks the canteen owner personally", "It relies on a famous person''s opinion", "It uses circular reasoning"]', 0, 'There are clearly other choices, like changing the menu, so presenting just two options is a false dilemma.', '{"1": "No person is attacked.", "2": "No authority is quoted.", "3": "The conclusion is not assumed in the premise."}'),
  ('LR-0249', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"A famous cricketer says this herbal powder cures diabetes, so it must work."
What is the flaw?', '["It confuses cause and effect", "It relies on an authority who has no expertise in medicine", "It generalises from one patient", "It attacks the cricketer''s character"]', 1, 'A cricketer''s fame does not make him an expert on diabetes treatment. This is an appeal to an irrelevant authority.', '{"0": "No cause-and-effect pair is reversed.", "2": "No patient results are mentioned.", "3": "The cricketer is praised, not attacked."}'),
  ('LR-0250', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"Every player in our team is excellent, so our team must be excellent."
What is the flaw in this reasoning?', '["It assumes the whole must be true of each part", "It uses an unrelated authority", "It assumes that what is true of each part must be true of the whole", "It reverses cause and effect"]', 2, 'Excellent individuals may still play badly together. Assuming the whole shares the qualities of its parts is the fallacy of composition.', '{"0": "That is the opposite error (division).", "1": "No authority is used.", "3": "No causal claim is reversed."}'),
  ('LR-0251', 'Logical Reasoning', 'Critical thinking', 'Logical fallacies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"I wore my new shoes on exam day and got excellent marks, so these shoes bring good luck."
This reasoning is flawed because:', '["It attacks the person who made the shoes", "It offers only two choices", "It relies on what most people believe", "It assumes that because one thing happened after another, the first caused the second"]', 3, 'Getting good marks after wearing the shoes does not show the shoes caused it. This is the ''after this, therefore because of this'' (post hoc) error.', '{"0": "No one is attacked.", "1": "No choice is offered.", "2": "Popular opinion is not mentioned."}'),
  ('LR-0252', 'Logical Reasoning', 'Critical thinking', 'Drawing inferences', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', 'In a survey of 500 MDCAT candidates, 300 had used online practice tests. Of these 300, 240 said the tests helped them.
Which statement MUST be true?', '["Fewer than half of all 500 candidates said online tests helped them", "Online practice tests improve MDCAT scores", "60 of the candidates who used online tests said the tests did not help", "Most of the 500 candidates said online tests helped them"]', 0, '240 is less than half of 500 (250), so fewer than half of all candidates said the tests helped.', '{"1": "The survey records opinions, not scores.", "2": "The other 60 may have been unsure or said nothing; we are not told they said the tests did not help.", "3": "240 out of 500 is 48%, which is not most."}'),
  ('LR-0253', 'Logical Reasoning', 'Critical thinking', 'Drawing inferences', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', 'All the wards in a hospital that have air-conditioning are on the upper floors. Ward 7 is on the ground floor.
Which must be true?', '["Ward 7 is a children''s ward", "Ward 7 does not have air-conditioning", "All upper-floor wards have air-conditioning", "Ward 7 will get air-conditioning soon"]', 1, 'Every air-conditioned ward is upstairs. Ward 7 is not upstairs, so it cannot be air-conditioned.', '{"0": "The type of ward is not mentioned.", "2": "This reverses the statement; some upper-floor wards may lack it.", "3": "Nothing is said about future plans."}'),
  ('LR-0254', 'Logical Reasoning', 'Critical thinking', 'Drawing inferences', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', 'Medicine X lowers blood pressure in most patients but causes dizziness in some. Doctors prescribe it only to patients whose blood pressure is very high.
What can most reasonably be inferred?', '["Medicine X does not work for mild high blood pressure", "Dizziness is caused by high blood pressure", "Doctors judge that for patients with very high blood pressure the benefit outweighs the risk of dizziness", "Every patient who takes Medicine X becomes dizzy"]', 2, 'Restricting a useful but risky medicine to severe cases suggests a weighing of benefit against side effects.', '{"0": "It may work in mild cases; doctors may just think the risk is not worth it there.", "1": "The passage says the medicine causes dizziness.", "3": "Only some patients get dizzy."}'),
  ('LR-0255', 'Logical Reasoning', 'Critical thinking', 'Drawing inferences', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', 'Every candidate who scored above 180 was offered an interview. Nobody who failed to submit documents was offered an interview. Zain submitted his documents but was not offered an interview.
Which must be true?', '["Zain scored exactly 180", "Zain''s documents were incomplete", "Everyone who submitted documents got an interview", "Zain did not score above 180"]', 3, 'Anyone scoring above 180 got an interview. Zain did not, so he did not score above 180.', '{"0": "He may have scored any mark up to 180.", "1": "We are told he submitted them; nothing says they were incomplete.", "2": "Zain submitted documents and got none, so this is false."}'),
  ('LR-0256', 'Logical Reasoning', 'Critical thinking', 'Resolving a paradox', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'After a town opened its first hospital, the number of recorded illnesses in the town went UP.
Which fact best explains this?', '["With a hospital nearby, many more sick people are now seen and recorded", "The hospital was built by a foreign company", "Most people in the town are farmers", "The hospital has a large car park"]', 0, 'Illnesses that used to go untreated and unrecorded are now diagnosed, so the recorded figure rises even if people are no sicker.', '{"1": "Who built it does not explain more records.", "2": "Occupation does not explain the rise after the hospital opened.", "3": "Parking is irrelevant."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0257', 'Logical Reasoning', 'Critical thinking', 'Resolving a paradox', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'A clinic hired three more doctors, yet the average waiting time for patients became LONGER.
Which fact best explains this?', '["The new doctors are well qualified", "News of the extra doctors drew many more patients from nearby towns", "The clinic repainted its waiting room", "Patients prefer morning appointments"]', 1, 'If the number of patients rose faster than the number of doctors, waits would grow despite the new hires.', '{"0": "Good qualifications would shorten waits, not lengthen them.", "2": "Paint does not affect waiting times.", "3": "A preference for mornings existed before and does not explain the change."}'),
  ('LR-0258', 'Logical Reasoning', 'Critical thinking', 'Resolving a paradox', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'A company halved the price of its medicine, yet its total income from that medicine ROSE.
Which fact best explains this?', '["The company makes other medicines too", "The medicine''s packaging was changed", "Sales more than doubled because many more patients could now afford it", "The cost of raw materials went up"]', 2, 'Income = price × number sold. If the price halves but sales more than double, income rises.', '{"0": "Other products do not explain income from this medicine.", "1": "Packaging alone does not explain higher income.", "3": "Higher costs would lower profit; they do not explain higher income."}'),
  ('LR-0259', 'Logical Reasoning', 'Critical thinking', 'Necessary and sufficient conditions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', '"A valid ID card is necessary, but not sufficient, to sit the exam."
Which statement must be true?', '["Anyone with a valid ID card can sit the exam", "Some people without an ID card sit the exam", "An ID card is the only document needed", "Everyone who sits the exam has a valid ID card"]', 3, '''Necessary'' means nobody sits without one. ''Not sufficient'' means having one is not enough on its own.', '{"0": "That would make the ID card sufficient.", "1": "That contradicts ''necessary''.", "2": "''Not sufficient'' implies something else is also needed."}'),
  ('LR-0260', 'Logical Reasoning', 'Critical thinking', 'Necessary and sufficient conditions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.1', '"Rain is sufficient to make the roads wet."
Which situation is IMPOSSIBLE if this statement is true?', '["It rained, but the roads stayed dry", "The roads are wet, but it did not rain", "It did not rain, and the roads are dry", "It rained, and the roads are wet"]', 0, 'If rain is sufficient, rain always makes the roads wet. So rain with dry roads cannot happen. Wet roads without rain are still possible (for example, a burst pipe).', '{"1": "Something else, like a burst pipe, could wet the roads.", "2": "No rain and dry roads is entirely possible.", "3": "This is exactly what the statement predicts."}'),
  ('LR-0261', 'Logical Reasoning', 'Critical thinking', 'Evaluating evidence', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'Which piece of evidence best supports the claim that contaminated well water caused a diarrhoea outbreak in a village?', '["Many villagers had diarrhoea", "Families who boiled their water had far fewer cases than families who drank it straight from the well", "Water is essential for health", "The outbreak happened in summer"]', 1, 'Comparing families who did and did not treat the water ties the illness to the water itself.', '{"0": "This shows there was an outbreak, not its cause.", "2": "This is true but does not link the well to the outbreak.", "3": "Season alone does not point to the well."}'),
  ('LR-0262', 'Logical Reasoning', 'Critical thinking', 'Evaluating evidence', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.2', 'Which source gives the most reliable evidence that a new vaccine is safe?', '["Personal stories shared by people who took it", "An advertisement from the company that makes it", "A large controlled trial whose results were independently reviewed before publication", "A popular social media post"]', 2, 'A large controlled, independently reviewed trial compares vaccinated and unvaccinated groups and checks the work, which makes it far more reliable.', '{"0": "Personal stories are few and unchecked.", "1": "The maker has an interest in praising it.", "3": "Popularity is not evidence."}'),
  ('LR-0263', 'Logical Reasoning', 'Critical thinking', 'Evaluating evidence', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', 'An advertisement says: "9 out of 10 dentists surveyed recommend Brand Z toothpaste, so it is the best toothpaste you can buy."
What is the most serious weakness in this claim?', '["Toothpaste comes in many flavours", "Some people do not visit dentists", "Dentists are busy professionals", "We are not told how the dentists were chosen or which other brands they were asked to compare"]', 3, 'If the survey picked friendly dentists, or asked only ''Is Brand Z acceptable?'', the 9 out of 10 figure would not show Brand Z is the best. The claim depends on details it hides.', '{"0": "Flavours do not affect whether the survey supports ''best''.", "1": "Who visits dentists is irrelevant to the survey''s quality.", "2": "Being busy does not weaken the survey''s result."}'),
  ('LR-0264', 'Logical Reasoning', 'Critical thinking', 'Weakening an argument', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.1.3', '"To end traffic jams on the main road, the city should widen it from four lanes to six."
Which fact, if true, most WEAKENS this plan?', '["In many cities, widened roads soon attract more cars, and jams return to the same level within a few years", "Road widening creates construction jobs", "The main road was built twenty years ago", "Six-lane roads need more road markings"]', 0, 'If extra lanes simply draw more traffic, the plan will not end the jams it is meant to solve.', '{"1": "Jobs do not show whether jams will end.", "2": "The road''s age is irrelevant.", "3": "Road markings are a minor detail, not a reason the plan would fail."}'),
  ('LR-0265', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What comes next in the series?
0.5, 1.5, 4.5, 13.5, ?', '["40.5", "27", "39", "40"]', 0, 'Each term is 3 times the one before (common ratio 3): 13.5 × 3 = 40.5.', '{"1": "27 is 13.5 × 2; the ratio is 3, not 2.", "2": "39 adds 25.5, but the series multiplies rather than adds.", "3": "40 is close but ignores the exact ratio: 13.5 × 3 = 40.5."}'),
  ('LR-0266', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What comes next in the series?
64, 48, 36, 27, ?', '["18", "20.25", "21", "20"]', 1, 'The common ratio is 48/64 = 3/4, so the next term is 27 × 3/4 = 20.25.', '{"0": "18 subtracts 9 again, but the differences (16, 12, 9) also shrink by 3/4 each time.", "2": "21 subtracts 6, but the terms are multiplied by 3/4 each time.", "3": "20 rounds the answer; 27 × 0.75 is exactly 20.25."}'),
  ('LR-0267', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'In the geometric progression 3, 6, 12, 24, …, what is the 8th term?', '["192", "768", "384", "48"]', 2, 'The nth term of a geometric progression is a × r^(n−1). Here a = 3 and r = 2, so the 8th term is 3 × 2⁷ = 3 × 128 = 384.', '{"0": "192 is the 7th term (3 × 2⁶).", "1": "768 is the 9th term (3 × 2⁸).", "3": "48 is only the 5th term."}'),
  ('LR-0268', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'In a geometric progression, the 2nd term is 6 and the 5th term is 162. What is the 1st term?', '["3", "1", "6", "2"]', 3, 'Dividing the 5th term by the 2nd gives r³ = 162 ÷ 6 = 27, so r = 3. The 1st term is 6 ÷ 3 = 2 (series 2, 6, 18, 54, 162).', '{"0": "3 is the common ratio, not the first term.", "1": "With a first term of 1 and ratio 3, the 5th term would be 81, not 162.", "2": "6 is the 2nd term."}'),
  ('LR-0269', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What is the sum of the first six terms of the series 1, 3, 9, 27, …?', '["364", "243", "121", "1093"]', 0, 'The terms are 1, 3, 9, 27, 81, 243. Their sum is 364 (or use (3⁶ − 1) ÷ (3 − 1) = 728 ÷ 2 = 364).', '{"1": "243 is the 6th term on its own, not the sum.", "2": "121 is the sum of only the first five terms.", "3": "1093 is the sum of the first seven terms."}'),
  ('LR-0270', 'Logical Reasoning', 'Patterns and sequences', 'Mathematical operations', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'If + means ×, × means −, − means ÷ and ÷ means +, what is the value of:
16 − 4 + 3 × 2 ÷ 5', '["5", "15", "19", "10"]', 1, 'Replacing the signs gives 16 ÷ 4 × 3 − 2 + 5. Using BODMAS: 16 ÷ 4 = 4, 4 × 3 = 12, then 12 − 2 + 5 = 15.', '{"0": "5 subtracts 5 instead of adding it (÷ means +).", "2": "19 adds 2 instead of subtracting it (× means −).", "3": "10 forgets to change + into ×, giving 16 ÷ 4 + 3 − 2 + 5."}'),
  ('LR-0271', 'Logical Reasoning', 'Patterns and sequences', 'Mathematical operations', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'If P means +, Q means −, R means × and S means ÷, what is the value of:
36 S 4 P 5 R 3 Q 8', '["34", "19", "16", "32"]', 2, 'The expression is 36 ÷ 4 + 5 × 3 − 8 = 9 + 15 − 8 = 16 (divide and multiply before adding and subtracting).', '{"0": "34 works left to right without BODMAS: ((9 + 5) × 3) − 8.", "1": "19 subtracts 5 instead of 8.", "3": "32 adds 8 instead of subtracting it."}'),
  ('LR-0272', 'Logical Reasoning', 'Patterns and sequences', 'Mathematical operations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'If the signs + and × are interchanged and the numbers 4 and 6 are interchanged, which equation becomes correct?', '["6 + 4 × 2 = 14", "6 × 4 + 2 = 20", "4 + 6 × 2 = 16", "4 × 6 + 2 = 14"]', 3, 'After the swaps, 4 × 6 + 2 = 14 becomes 6 + 4 × 2 = 14, and 6 + 8 = 14 is true.', '{"0": "After the swaps it becomes 4 × 6 + 2 = 14, which is 26 = 14, false.", "1": "After the swaps it becomes 4 + 6 × 2 = 20, which is 16 = 20, false.", "2": "After the swaps it becomes 6 × 4 + 2 = 16, which is 26 = 16, false."}'),
  ('LR-0273', 'Logical Reasoning', 'Patterns and sequences', 'Missing number', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Find the missing number. The same rule applies to every row.
Row 1: 3, 4, 25
Row 2: 5, 12, 169
Row 3: 8, 15, ?', '["289", "23", "120", "256"]', 0, 'In each row the third number is the sum of the squares of the first two: 3² + 4² = 25, 5² + 12² = 169, so 8² + 15² = 64 + 225 = 289.', '{"1": "23 just adds 8 and 15.", "2": "120 multiplies 8 by 15.", "3": "256 is 16², not 8² + 15²."}'),
  ('LR-0274', 'Logical Reasoning', 'Patterns and sequences', 'Missing number', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Find the missing number. The same rule applies to every row.
Row 1: 9, 4, 65
Row 2: 6, 1, 35
Row 3: 7, 5, ?', '["12", "24", "74", "35"]', 1, 'The third number is the first squared minus the second squared: 9² − 4² = 81 − 16 = 65 and 6² − 1² = 35. So 7² − 5² = 49 − 25 = 24.', '{"0": "12 is 7 + 5, which does not fit rows 1 and 2.", "2": "74 is 7² + 5², a sum rather than a difference.", "3": "35 is 7 × 5, which does not fit row 1 (9 × 4 = 36)."}'),
  ('LR-0275', 'Logical Reasoning', 'Patterns and sequences', 'Letter, number and symbol series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'Study the arrangement:
K 4 @ M 7 # 2 P $ 9 R % 5 & T 3
Which element is 3rd to the right of the 10th element from the left?', '["%", "&", "5", "R"]', 2, 'The 10th element from the left is 9. Counting three places to its right gives R, %, 5, so the answer is 5.', '{"0": "% is only 2nd to the right of 9.", "1": "& is 4th to the right of 9.", "3": "R is 1st to the right of 9."}'),
  ('LR-0276', 'Logical Reasoning', 'Patterns and sequences', 'Letter, number and symbol series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'Study the arrangement:
K 4 @ M 7 # 2 P $ 9 R % 5 & T 3
How many numbers are immediately preceded by a symbol AND immediately followed by a letter?', '["1", "3", "4", "2"]', 3, 'Check each number: 4 (after K), 7 (after M), 2 (after #, before P), 9 (after $, before R), 5 (after %, before &), 3 (after T, at the end). Only 2 and 9 meet both conditions.', '{"0": "One misses either # 2 P or $ 9 R.", "1": "Three wrongly counts % 5 &, but 5 is followed by a symbol, not a letter.", "2": "Four counts numbers that fail one of the conditions."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0277', 'Logical Reasoning', 'Patterns and sequences', 'Letter, number and symbol series', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the symbol series?
* # # * * * # # # # ?', '["*", "#", "* *", "# *"]', 0, 'The groups grow by one: *, ##, ***, ####. The next group is five stars, so the next symbol is *.', '{"1": "# would make the fourth group five long, but it already has four.", "2": "The question asks for the next single symbol.", "3": "The question asks for the next single symbol, and it starts a group of stars."}'),
  ('LR-0278', 'Logical Reasoning', 'Patterns and sequences', 'Alphabet positions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'If the English alphabet is written in reverse order (Z first, A last), which letter is 7th to the right of the 12th letter from the left?', '["V", "H", "G", "I"]', 1, 'In reverse order the 12th letter from the left is O (Z=1, Y=2 … O=12). Seven places to its right is the 19th letter, which is H.', '{"0": "V comes from counting in the wrong direction (to the left of O).", "2": "G is 8th to the right, one too far.", "3": "I is 6th to the right, one short."}'),
  ('LR-0279', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
3, 7, 16, 35, 74, ?', '["148", "149", "153", "150"]', 2, 'Each term is doubled and then 1, 2, 3, 4, … is added: 3×2+1 = 7, 7×2+2 = 16, 16×2+3 = 35, 35×2+4 = 74, so 74×2+5 = 153.', '{"0": "148 just doubles 74 without the growing addition.", "1": "149 adds 1 every time, but the addition grows by 1 each step.", "3": "150 adds 2, repeating the second step''s addition."}'),
  ('LR-0280', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
1, 2, 6, 15, 31, 56, ?', '["87", "81", "97", "92"]', 3, 'The differences are 1, 4, 9, 16, 25, which are the squares 1², 2², 3², 4², 5². The next difference is 6² = 36, so 56 + 36 = 92.', '{"0": "87 adds 31, which is a term of the series, not the next square (36).", "1": "81 adds 25 again instead of 36.", "2": "97 adds 41, as if the differences grew by a fixed amount."}'),
  ('LR-0281', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
2, 3, 10, 15, 26, 35, 50, ?', '["63", "65", "64", "61"]', 0, 'The terms are n² + 1 for odd n and n² − 1 for even n: 1+1, 4−1, 9+1, 16−1, 25+1, 36−1, 49+1. The 8th term is 8² − 1 = 63.', '{"1": "65 is 8² + 1, but 8 is even, so 1 is subtracted.", "2": "64 is just 8².", "3": "61 adds 11, repeating an earlier difference."}'),
  ('LR-0282', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
0, 7, 26, 63, 124, ?', '["217", "215", "185", "199"]', 1, 'Each term is one less than a cube: 1³−1 = 0, 2³−1 = 7, 3³−1 = 26, 4³−1 = 63, 5³−1 = 124, so the next is 6³ − 1 = 215.', '{"0": "217 is 6³ + 1; the series subtracts 1.", "2": "185 adds 61, the previous difference, again.", "3": "199 adds 75 by guessing the differences rise by 14."}'),
  ('LR-0283', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
2, 12, 36, 80, 150, ?', '["240", "216", "252", "230"]', 2, 'Each term is n³ + n², which is n²(n + 1): 1×2, 4×3, 9×4, 16×5, 25×6. The next is 36 × 7 = 252.', '{"0": "240 adds 90, which does not follow n²(n + 1).", "1": "216 is just 6³ and leaves out the 6² part.", "3": "230 adds 80, guessing the differences grow by 10."}'),
  ('LR-0284', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
3, 20, 6, 17, 12, 14, 24, 11, ?', '["8", "36", "27", "48"]', 3, 'Two series are interleaved. The 1st, 3rd, 5th, 7th terms double (3, 6, 12, 24) and the 2nd, 4th, 6th, 8th terms fall by 3 (20, 17, 14, 11). The 9th term belongs to the doubling series: 24 × 2 = 48.', '{"0": "8 continues the falling series, but the 9th term belongs to the doubling one.", "1": "36 adds 12 to 24 instead of doubling.", "2": "27 adds 3 to 24, mixing the two rules."}'),
  ('LR-0285', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
120, 99, 80, 63, 48, ?', '["35", "33", "36", "38"]', 0, 'The terms are one less than falling squares: 11²−1, 10²−1, 9²−1, 8²−1, 7²−1. The next is 6² − 1 = 35. (The differences 21, 19, 17, 15 fall by 2, giving 13.)', '{"1": "33 subtracts 15 again instead of 13.", "2": "36 is 6² without subtracting 1.", "3": "38 subtracts 10."}'),
  ('LR-0286', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What comes next in the series?
1, 4, 27, 256, ?', '["625", "3125", "1024", "1250"]', 1, 'Each term is n raised to its own power: 1¹, 2², 3³, 4⁴. The next is 5⁵ = 3125.', '{"0": "625 is 5⁴, not 5⁵.", "2": "1024 is 4⁵ (or 2¹⁰).", "3": "1250 is 256 multiplied by about 5, not a power rule."}'),
  ('LR-0287', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What comes next in the series?
4, 7, 13, 25, 49, ?', '["73", "98", "97", "96"]', 2, 'Each term is double the previous one minus 1: 4×2−1 = 7, 7×2−1 = 13, 13×2−1 = 25, 25×2−1 = 49, so 49×2−1 = 97. (The differences 3, 6, 12, 24 double each time, so the next is 48.)', '{"0": "73 adds 24 again instead of 48.", "1": "98 doubles 49 but forgets to subtract 1.", "3": "96 subtracts 2 instead of 1."}'),
  ('LR-0288', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
1, 8, 9, 64, 25, 216, ?', '["343", "36", "512", "49"]', 3, 'The series alternates squares of odd positions and cubes of even positions: 1², 2³, 3², 4³, 5², 6³. The 7th term is 7² = 49.', '{"0": "343 is 7³; the 7th position takes a square.", "1": "36 is 6², but the 6th position took a cube and the next number is 7.", "2": "512 is 8³, which would be the 8th term."}'),
  ('LR-0289', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
6, 24, 60, 120, 210, ?', '["336", "300", "330", "320"]', 0, 'Each term is the product of three consecutive numbers: 1·2·3, 2·3·4, 3·4·5, 4·5·6, 5·6·7. The next is 6·7·8 = 336.', '{"1": "300 adds 90, the previous difference, again.", "2": "330 adds 120, guessing differences rise by 30.", "3": "320 does not come from any consistent rule."}'),
  ('LR-0290', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
1, 3, 4, 7, 11, 18, ?', '["25", "29", "27", "36"]', 1, 'From the third term on, each term is the sum of the two before it: 1+3 = 4, 3+4 = 7, 4+7 = 11, 7+11 = 18, so 11 + 18 = 29.', '{"0": "25 adds 7, the difference two steps back.", "2": "27 adds 9 by guessing the differences.", "3": "36 doubles 18."}'),
  ('LR-0291', 'Logical Reasoning', 'Patterns and sequences', 'Wrong number in a series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Which number does NOT fit the series?
1, 3, 7, 15, 31, 63, 125, 255', '["63", "255", "125", "31"]', 2, 'Each term is double the previous plus 1 (2ⁿ − 1): 1, 3, 7, 15, 31, 63, 127, 255. So 125 should be 127.', '{"0": "63 = 31 × 2 + 1 fits.", "1": "255 = 127 × 2 + 1 fits once 125 is corrected to 127.", "3": "31 = 15 × 2 + 1 fits."}'),
  ('LR-0292', 'Logical Reasoning', 'Patterns and sequences', 'Wrong number in a series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'Which number does NOT fit the series?
3, 12, 48, 190, 768', '["48", "768", "12", "190"]', 3, 'This is a geometric series with ratio 4: 3, 12, 48, 192, 768. So 190 should be 192.', '{"0": "48 = 12 × 4 fits.", "1": "768 = 192 × 4 fits once 190 is corrected.", "2": "12 = 3 × 4 fits."}'),
  ('LR-0293', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
4, 9, 25, 49, 121, ?', '["169", "144", "225", "196"]', 0, 'The terms are squares of prime numbers: 2², 3², 5², 7², 11². The next prime is 13, so the answer is 13² = 169.', '{"1": "144 = 12², but 12 is not prime.", "2": "225 = 15², but 15 is not prime.", "3": "196 = 14², but 14 is not prime."}'),
  ('LR-0294', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
B, E, J, Q, ?', '["X", "Z", "Y", "W"]', 1, 'The letter positions are 2, 5, 10, 17, which are n² + 1 (differences 3, 5, 7). The next difference is 9, giving 26 = Z.', '{"0": "X (24) adds 7 again instead of 9.", "2": "Y (25) adds 8.", "3": "W (23) adds 6."}'),
  ('LR-0295', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
AZ, CX, FU, JQ, ?', '["NL", "OM", "OL", "PK"]', 2, 'First letters move forward by 2, 3, 4, 5: A, C, F, J, O. Second letters move back by 2, 3, 4, 5: Z, X, U, Q, L. So the answer is OL.', '{"0": "N moves the first letter forward by 4 again instead of 5.", "1": "M moves the second letter back by 4 again instead of 5.", "3": "P and K move both letters by 6."}'),
  ('LR-0296', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
Z, W, S, P, L, I, ?', '["F", "D", "G", "E"]', 3, 'The letters step back alternately by 3 and 4: Z→W (3), W→S (4), S→P (3), P→L (4), L→I (3). The next step is 4: I (9) → E (5).', '{"0": "F steps back 3 again; the steps alternate 3 and 4.", "1": "D steps back 5.", "2": "G steps back 2."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0297', 'Logical Reasoning', 'Patterns and sequences', 'Letter and number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
A1Z, C3X, E5V, G7T, ?', '["I9R", "H9S", "I8R", "I9S"]', 0, 'The first letter moves on by 2 (A, C, E, G, I), the number goes up by 2 (1, 3, 5, 7, 9) and the last letter moves back by 2 (Z, X, V, T, R). The number also equals the position of the first letter.', '{"1": "H moves the first letter by only 1, and S moves the last back by only 1.", "2": "The number rises by 2 each time, so 8 is wrong.", "3": "S moves the last letter back by 1, not 2."}'),
  ('LR-0298', 'Logical Reasoning', 'Patterns and sequences', 'Coding and decoding', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'In a certain code, MEDICINE is written as FOJDJEFN. How is DOCTOR written in that code?', '["EPDUPS", "SPUDPE", "SPUDPF", "QNSBNC"]', 1, 'Each letter is moved one place forward (MEDICINE → NFEJDJOF) and then the word is written backwards (FOJDJEFN). For DOCTOR: EPDUPS, reversed = SPUDPE.', '{"0": "EPDUPS shifts the letters but forgets to reverse the word.", "2": "SPUDPF changes the last letter wrongly: D + 1 = E.", "3": "QNSBNC shifts backwards instead of forwards."}'),
  ('LR-0299', 'Logical Reasoning', 'Patterns and sequences', 'Coding and decoding', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'In a code, every letter is replaced by the letter in the mirror position of the alphabet (A↔Z, B↔Y, C↔X and so on). How is HEART written?', '["SVZIH", "IFBSU", "SVZIG", "TVZIG"]', 2, 'Mirror pairs add up to 27: H(8)↔S(19), E(5)↔V(22), A(1)↔Z(26), R(18)↔I(9), T(20)↔G(7). So HEART = SVZIG.', '{"0": "T (20) pairs with G (7), not H.", "1": "IFBSU just shifts each letter forward by one.", "3": "H (8) pairs with S (19), not T."}'),
  ('LR-0300', 'Logical Reasoning', 'Patterns and sequences', 'Coding and decoding', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'In a code, CAT = 72 and DOG = 78. What is BOOK in that code?', '["43", "129", "176", "172"]', 3, 'The code is (sum of letter positions) × (number of letters): CAT = (3+1+20) × 3 = 72 and DOG = (4+15+7) × 3 = 78. BOOK = (2+15+15+11) × 4 = 43 × 4 = 172.', '{"0": "43 is only the sum of the positions, without multiplying by 4.", "1": "129 multiplies by 3, but BOOK has 4 letters.", "2": "176 is 44 × 4; the sum of the positions is 43."}'),
  ('LR-0301', 'Logical Reasoning', 'Patterns and sequences', 'Analogy', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'ACE : FHJ :: KMO : ?', '["PRT", "LNP", "QSU", "PQR"]', 0, 'Each letter of ACE moves forward 5 places to make FHJ (A→F, C→H, E→J). Doing the same to KMO gives PRT.', '{"1": "LNP moves each letter by only 1.", "2": "QSU moves each letter by 6.", "3": "PQR keeps the first move but loses the 2-letter gaps."}'),
  ('LR-0302', 'Logical Reasoning', 'Patterns and sequences', 'Analogy', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', '5 : 124 :: 3 : ?', '["24", "26", "27", "8"]', 1, '124 = 5³ − 1, so the rule is n³ − 1. For 3 that gives 27 − 1 = 26.', '{"0": "24 would need a different rule, such as 3 × 8.", "2": "27 is 3³ but forgets to subtract 1.", "3": "8 is 3² − 1, using a square instead of a cube."}'),
  ('LR-0303', 'Logical Reasoning', 'Patterns and sequences', 'Odd one out', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Which number is the odd one out?
121, 169, 225, 289, 361', '["121", "289", "225", "361"]', 2, '121, 169, 289 and 361 are squares of prime numbers (11, 13, 17, 19). 225 is 15², and 15 is not prime.', '{"0": "121 = 11², and 11 is prime.", "1": "289 = 17², and 17 is prime.", "3": "361 = 19², and 19 is prime."}'),
  ('LR-0304', 'Logical Reasoning', 'Patterns and sequences', 'Odd one out', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'Which group of letters is the odd one out?
BDF, HJL, NPR, MOR, TVX', '["BDF", "NPR", "TVX", "MOR"]', 3, 'In BDF, HJL, NPR and TVX the letters are 2 apart (skipping one letter). In MOR the gaps are 2 and 3.', '{"0": "B, D, F are equally spaced (gap 2).", "1": "N, P, R are equally spaced (gap 2).", "2": "T, V, X are equally spaced (gap 2)."}'),
  ('LR-0305', 'Logical Reasoning', 'Patterns and sequences', 'Odd one out', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Which number is the odd one out?
27, 64, 125, 196, 343', '["196", "27", "125", "343"]', 0, '27, 64, 125 and 343 are perfect cubes (3³, 4³, 5³, 7³). 196 is 14², a square but not a cube.', '{"1": "27 = 3³.", "2": "125 = 5³.", "3": "343 = 7³."}'),
  ('LR-0306', 'Logical Reasoning', 'Patterns and sequences', 'Missing number', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Find the missing number. The same rule applies to every column.
Column 1: 4, 5, 3, 60
Column 2: 2, 7, 4, 56
Column 3: 6, 3, ?, 54', '["2", "3", "4", "9"]', 1, 'The bottom number is the product of the three above it: 4×5×3 = 60, 2×7×4 = 56. So 6 × 3 × ? = 54 gives ? = 3.', '{"0": "2 would give 6×3×2 = 36.", "2": "4 would give 72.", "3": "9 would make 6 + 3 + 9 = 18; the rule is a product, not a sum."}'),
  ('LR-0307', 'Logical Reasoning', 'Patterns and sequences', 'Missing number', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Find the missing number.
2 → 5, 3 → 10, 4 → 17, 6 → ?, 9 → 82', '["36", "26", "37", "35"]', 2, 'Each output is the input squared plus 1: 2²+1 = 5, 3²+1 = 10, 4²+1 = 17, 9²+1 = 82. So 6² + 1 = 37.', '{"0": "36 is 6² without adding 1.", "1": "26 is 5² + 1, using the wrong input.", "3": "35 is 6² − 1."}'),
  ('LR-0308', 'Logical Reasoning', 'Patterns and sequences', 'Alphabet positions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'In the English alphabet, how many letters lie between the 5th letter from the left and the 9th letter from the right?', '["13", "11", "14", "12"]', 3, 'The 5th letter from the left is E (5). The 9th from the right is R (26 − 9 + 1 = 18). The letters between them are positions 6 to 17, which is 12 letters.', '{"0": "13 counts one of the end letters too.", "1": "11 drops one letter from the gap.", "2": "14 counts both end letters."}'),
  ('LR-0309', 'Logical Reasoning', 'Patterns and sequences', 'Alphabet positions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'In the word FORMULATE, how many pairs of letters have as many letters between them in the word as in the English alphabet (counting both forwards and backwards)?', '["1", "2", "0", "3"]', 0, 'Only O and M fit: in FORMULATE they have one letter (R) between them, and in the alphabet they have one letter (N) between them. Checking every other pair finds no further match, so the answer is 1.', '{"1": "Only one pair (O, M) fits; no second pair has matching gaps.", "2": "O and M do fit: one letter between them in the word and in the alphabet.", "3": "Only one pair fits."}'),
  ('LR-0310', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What comes next in the series?
1/2, 1/6, 1/18, ?', '["1/36", "1/54", "1/24", "1/72"]', 1, 'Each term is the previous one divided by 3 (common ratio 1/3): (1/18) × (1/3) = 1/54.', '{"0": "1/36 halves 1/18 instead of dividing by 3.", "2": "1/24 adds 6 to the denominator, but denominators are multiplied by 3.", "3": "1/72 multiplies the denominator by 4."}'),
  ('LR-0311', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
1, 2, 5, 14, 41, ?', '["123", "82", "122", "121"]', 2, 'Each term is three times the previous term minus 1: 1×3−1 = 2, 2×3−1 = 5, 5×3−1 = 14, 14×3−1 = 41, so 41×3−1 = 122.', '{"0": "123 is 41 × 3 without subtracting 1.", "1": "82 doubles 41.", "3": "121 subtracts 2 instead of 1."}'),
  ('LR-0312', 'Logical Reasoning', 'Patterns and sequences', 'Geometric progression', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.2', 'What comes next in the series?
4, 6, 9, 13.5, ?', '["18", "19.5", "27", "20.25"]', 3, 'Each term is 1.5 times the previous one (ratio 3/2): 13.5 × 1.5 = 20.25.', '{"0": "18 adds 4.5, the previous difference.", "1": "19.5 adds 6 by guessing the differences.", "2": "27 doubles 13.5."}'),
  ('LR-0313', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
6, 11, 21, 36, 56, ?', '["81", "76", "86", "71"]', 0, 'The differences are 5, 10, 15, 20, rising by 5 each time. The next difference is 25: 56 + 25 = 81.', '{"1": "76 adds 20 again.", "2": "86 adds 30, skipping 25.", "3": "71 adds only 15."}'),
  ('LR-0314', 'Logical Reasoning', 'Patterns and sequences', 'Letter series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'What comes next in the series?
C, G, L, R, ?', '["X", "Y", "Z", "W"]', 1, 'The positions are 3, 7, 12, 18 (gaps 4, 5, 6). The next gap is 7: 18 + 7 = 25, which is Y.', '{"0": "X (24) uses a gap of 6 again.", "2": "Z (26) uses a gap of 8.", "3": "W (23) uses a gap of 5."}'),
  ('LR-0315', 'Logical Reasoning', 'Patterns and sequences', 'Number series', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'What comes next in the series?
3, 12, 27, 48, 75, ?', '["102", "105", "108", "111"]', 2, 'Each term is 3n²: 3×1, 3×4, 3×9, 3×16, 3×25. The next is 3 × 36 = 108. (The differences 9, 15, 21, 27 rise by 6, so the next is 33.)', '{"0": "102 adds 27 again.", "1": "105 adds 30.", "3": "111 adds 36."}'),
  ('LR-0316', 'Logical Reasoning', 'Patterns and sequences', 'Odd one out', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.1', 'Three of these number pairs follow the same rule. Which pair is the odd one out?', '["(2, 8)", "(3, 27)", "(4, 64)", "(5, 120)"]', 3, 'In (2, 8), (3, 27) and (4, 64) the second number is the cube of the first. 5³ = 125, not 120.', '{"0": "2³ = 8 fits.", "1": "3³ = 27 fits.", "2": "4³ = 64 fits."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0317', 'Logical Reasoning', 'Patterns and sequences', 'Analogy', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.2.3', 'Ornithology : Birds :: Entomology : ?', '["Insects", "Words", "Fossils", "Fish"]', 0, 'Ornithology is the scientific study of birds; entomology is the scientific study of insects.', '{"1": "The study of word origins is etymology, a word often confused with entomology.", "2": "Fossils are studied in palaeontology.", "3": "Fish are studied in ichthyology."}'),
  ('LR-0318', 'Logical Reasoning', 'Logical deductions', 'Data sufficiency', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Question: Who is the tallest among P, Q and R?
Statement I: P is taller than Q.
Statement II: R is taller than P.
Which is enough to answer the question?', '["Statement I alone is sufficient", "Statement II alone is sufficient", "Both statements together are needed", "Each statement alone is sufficient"]', 2, 'Statement I alone leaves R unplaced, and II alone leaves Q unplaced. Together: R > P > Q, so R is the tallest.', '{"0": "I alone says nothing about R.", "1": "II alone says nothing about Q.", "3": "Neither statement is enough alone."}'),
  ('LR-0319', 'Logical Reasoning', 'Logical deductions', 'Data sufficiency', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Question: What is the value of the whole number x?
Statement I: x is a prime number between 20 and 30.
Statement II: x leaves a remainder of 1 when divided by 4.
Which is enough to answer the question?', '["Statement I alone is sufficient", "Statement II alone is sufficient", "Both statements together are needed", "Each statement alone is sufficient"]', 2, 'I alone allows 23 or 29. II alone allows 1, 5, 9, 13, … Together only 29 fits (23 leaves remainder 3).', '{"0": "I alone leaves two choices, 23 and 29.", "1": "II alone allows many numbers.", "3": "Neither statement is enough alone."}'),
  ('LR-0320', 'Logical Reasoning', 'Logical deductions', 'Data sufficiency', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Question: On which day did Aslam visit the clinic?
Statement I: He visited on the day after Wednesday.
Statement II: He visited on the day before Friday.
Which is enough to answer the question?', '["Statement I alone is sufficient", "Statement II alone is sufficient", "Both statements together are needed", "Each statement alone is sufficient"]', 3, 'Each statement alone gives Thursday, so either one is enough.', '{"0": "Statement II alone also gives Thursday.", "1": "Statement I alone also gives Thursday.", "2": "Neither statement needs the other."}'),
  ('LR-0321', 'Logical Reasoning', 'Logical deductions', 'Data sufficiency', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Question: How many students are in the class?
Statement I: Ali is 12th from the top and 18th from the bottom.
Statement II: There are 5 more boys than girls.
Which is enough to answer the question?', '["Statement I alone is sufficient", "Statement II alone is sufficient", "Both statements together are needed", "Each statement alone is sufficient"]', 0, 'Statement I alone gives 12 + 18 − 1 = 29 students. Statement II gives only a difference, not a total.', '{"1": "A difference of 5 fits many class sizes.", "2": "Statement I already answers it.", "3": "Statement II alone is not enough."}'),
  ('LR-0322', 'Logical Reasoning', 'Logical deductions', 'Data sufficiency', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Question: In a code language, what is the code for "sky"?
Statement I: "blue sky high" is written "ka po ri".
Statement II: "clear sky" is written "po te" and "clear water" is written "te mu".
Which is enough to answer the question?', '["Statement I alone is sufficient", "Statement II alone is sufficient", "Both statements together are needed", "Each statement alone is sufficient"]', 1, 'From II, ''clear'' is common to both phrases and ''te'' is common to both codes, so clear = te and therefore sky = po. Statement I alone cannot match the three words to the three codes.', '{"0": "I alone gives three words and three codes with no way to pair them.", "2": "II alone is enough.", "3": "I alone is not enough."}'),
  ('LR-0323', 'Logical Reasoning', 'Logical deductions', 'Data sufficiency', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Question: In which direction is the school from Hamza''s house?
Statement I: The school is 3 km north of the park.
Statement II: The park is 3 km east of Hamza''s house.
Which is enough to answer the question?', '["Statement I alone is sufficient", "Statement II alone is sufficient", "Both statements together are needed", "Each statement alone is sufficient"]', 2, 'Together: go 3 km east to the park, then 3 km north to the school. The school is north-east of the house. Neither statement alone links the school to the house.', '{"0": "I alone does not place the house.", "1": "II alone does not place the school.", "3": "Neither statement alone is enough."}'),
  ('LR-0324', 'Logical Reasoning', 'Logical deductions', 'Building on given information', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.2', 'In a group, 40 people speak Urdu, 25 speak English and 10 speak both. Everyone speaks at least one of the two. Later, 5 people who speak only English leave the group.
How many people are now in the group?', '["55", "60", "50", "45"]', 2, 'At first the group has 40 + 25 − 10 = 55 people (the 10 who speak both are counted once). After 5 leave, 50 remain.', '{"0": "55 is the size before anyone leaves.", "1": "60 forgets to subtract the 10 counted twice, then removes 5.", "3": "45 subtracts the 10 twice."}'),
  ('LR-0325', 'Logical Reasoning', 'Logical deductions', 'Building on given information', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.2', 'In a family, A has two children, B and C. B has a son, D. C has a daughter, E. Later D marries F and they have a son, G.
How is E related to G''s father?', '["Sister", "Aunt", "Niece", "Cousin"]', 3, 'G''s father is D. D is B''s son and E is C''s daughter, and B and C are siblings, so D and E are first cousins.', '{"0": "E and D have different parents.", "1": "E is at the same generation as D, not above.", "2": "E is at the same generation as D, not below."}'),
  ('LR-0326', 'Logical Reasoning', 'Logical deductions', 'Building on given information', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.2', 'Six books stand in a row, from left to right: P, Q, R, S, T, U.
First, P and U swap places. Then the book that is now 2nd from the right is moved to the far left.
Which book is now 4th from the left?', '["R", "S", "Q", "U"]', 0, 'After the swap the row is U, Q, R, S, T, P. The 2nd from the right is T; moving it to the far left gives T, U, Q, R, S, P. The 4th from the left is R.', '{"1": "S is 5th from the left.", "2": "Q is 3rd from the left.", "3": "U is 2nd from the left."}'),
  ('LR-0327', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Every nurse on the night shift has completed first-aid training. Some nurses on the night shift also work in the emergency ward. Nobody in the emergency ward is a trainee.
Which statement is most accurate?', '["Everyone in the emergency ward has first-aid training", "Some people with first-aid training are not trainees", "No trainee has first-aid training", "Some trainees work on the night shift"]', 1, 'The night-shift nurses who work in the emergency ward have first-aid training (all night nurses do) and are not trainees (nobody in emergency is). So some trained people are not trainees.', '{"0": "Only the night-shift nurses are known to be trained; other emergency staff may not be.", "2": "Trainees outside the emergency ward might be trained.", "3": "Nothing says any trainee works at night."}'),
  ('LR-0328', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'A library opens only on weekdays. On Mondays it closes at 2 pm; on the other weekdays it closes at 5 pm. Hamid was inside the library at 4 pm last week.
Which must be true?', '["Hamid visited on a Monday", "Hamid visited on a Saturday", "Hamid visited on a weekday other than Monday", "Hamid visits the library every day"]', 2, 'The library is closed at weekends, and at 4 pm on a Monday it is already closed. So Hamid''s visit was on Tuesday to Friday.', '{"0": "On Mondays it closes at 2 pm.", "1": "The library is closed on weekends.", "3": "Nothing suggests he visits every day."}'),
  ('LR-0329', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Every member of the debating club plays chess. Half of the chess players are in the science society. Zara is in the debating club.
Which must be true?', '["Zara is in the science society", "Half the debating club is in the science society", "Every chess player is in the debating club", "Zara plays chess"]', 3, 'All debaters play chess, and Zara is a debater, so she plays chess. Whether she is among the half in the science society is not known.', '{"0": "She may be in the half that is not.", "1": "The half refers to chess players, not debaters.", "2": "This reverses the first statement."}'),
  ('LR-0330', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All doctors are graduates.
Statement 2: Some graduates are poets.
Statement 3: No poet is a lazy person.
Conclusion I: Some doctors are poets.
Conclusion II: Some graduates are not lazy people.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 1, 'The graduates who are poets cannot be lazy, because no poet is lazy, so some graduates are not lazy (II follows). The doctors may or may not be among the poet-graduates, so I is not certain.', '{"0": "The graduates who are poets need not include any doctor.", "2": "Conclusion I is not certain.", "3": "Conclusion II is certain: the poet-graduates are not lazy."}'),
  ('LR-0331', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: Some boxes are bags.
Statement 2: No bag is a cup.
Conclusion I: Some boxes are not cups.
Conclusion II: No box is a cup.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'The boxes that are bags cannot be cups, so some boxes are not cups (I follows). Other boxes might still be cups, so ''no box is a cup'' is not certain.', '{"1": "Boxes that are not bags could be cups.", "2": "Conclusion II is not certain.", "3": "Conclusion I is certain."}'),
  ('LR-0332', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All cats are pets.
Statement 2: All pets are animals.
Conclusion I: All animals are cats.
Conclusion II: Some animals are cats.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 1, 'All cats are pets and all pets are animals, so all cats are animals, which means some animals are cats (II). ''All animals are cats'' reverses an ''all'' statement and does not follow.', '{"0": "''All cats are animals'' does not mean ''all animals are cats''.", "2": "Conclusion I does not follow.", "3": "Conclusion II follows from converting ''all cats are animals''."}'),
  ('LR-0333', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: Some keys are locks.
Statement 2: All locks are doors.
Statement 3: No door is a window.
Conclusion I: Some keys are not windows.
Conclusion II: Some doors are keys.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 2, 'The keys that are locks are also doors, and no door is a window, so those keys are not windows (I). Those same keys are doors, so some doors are keys (II). Both follow.', '{"0": "Conclusion II also follows: the key-locks are doors.", "1": "Conclusion I also follows: the key-locks are doors, and no door is a window.", "3": "Both conclusions follow through the keys that are locks."}'),
  ('LR-0334', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All pencils are sticks.
Statement 2: No stick is a ring.
Conclusion I: No ring is a pencil.
Conclusion II: Some rings are sticks.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'Every pencil is a stick and no stick is a ring, so no pencil is a ring, which is the same as ''no ring is a pencil'' (I). Conclusion II contradicts Statement 2.', '{"1": "No stick is a ring, so no ring is a stick.", "2": "Conclusion II is false, not just uncertain.", "3": "Conclusion I follows by combining the statements."}'),
  ('LR-0335', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: Some players are singers.
Statement 2: All singers are dancers.
Conclusion I: All players are dancers.
Conclusion II: Some players are not dancers.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither conclusion follows"]', 2, 'We only know that some players (the singers) are dancers. Either all players are dancers or some are not; exactly one of the two must be true, and they cannot both be false. So ''either I or II'' follows.', '{"0": "Players who are not singers might not be dancers.", "1": "All the players might be dancers.", "3": "I and II form a complementary pair: one of them must be true."}'),
  ('LR-0336', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: No apple is a mango.
Statement 2: Some mangoes are bananas.
Conclusion I: Some bananas are not apples.
Conclusion II: Some apples are bananas.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'The bananas that are mangoes cannot be apples (no apple is a mango), so some bananas are not apples (I). Nothing links apples to bananas directly, so II is uncertain.', '{"1": "Apples and bananas are linked only through mangoes, and apples are not mangoes.", "2": "Conclusion II is not certain.", "3": "Conclusion I follows through the mango-bananas."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0337', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All tables are chairs.
Statement 2: Some chairs are sofas.
Statement 3: All sofas are beds.
Conclusion I: Some beds are chairs.
Conclusion II: Some tables are beds.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 0, 'Some chairs are sofas and every sofa is a bed, so those chairs are beds: some beds are chairs (I). The chairs that are sofas need not include any table, so II is uncertain.', '{"1": "The tables may not be among the chairs that are sofas.", "2": "Conclusion II is not certain.", "3": "Conclusion I follows through the chairs that are sofas."}'),
  ('LR-0338', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: Some coins are not notes.
Statement 2: All notes are papers.
Conclusion I: Some coins are not papers.
Conclusion II: Some papers are notes.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 1, 'Every note is a paper, so some papers are notes (II). The coins that are not notes could still be papers, so I is not certain.', '{"0": "Coins that are not notes might still be papers.", "2": "Conclusion I is not certain.", "3": "Conclusion II follows by converting ''all notes are papers''."}'),
  ('LR-0339', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: No tile is a brick.
Statement 2: All bricks are blocks.
Conclusion I: No tile is a block.
Conclusion II: Some blocks are not tiles.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 1, 'The blocks that are bricks cannot be tiles, so some blocks are not tiles (II). Tiles might still be blocks that are not bricks, so I is not certain.', '{"0": "A tile could be a block that is not a brick.", "2": "Conclusion I is not certain.", "3": "Conclusion II follows through the bricks."}'),
  ('LR-0340', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All files are folders.
Statement 2: Some folders are drives.
Conclusion I: Some files are drives.
Conclusion II: All drives are files.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 3, 'The folders that are drives need not include any file, and nothing says every drive is a file. Neither conclusion is certain.', '{"0": "The folders that are drives may not be files.", "1": "Some drives may not even be folders.", "2": "Neither conclusion is certain."}'),
  ('LR-0341', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All poets are writers.
Statement 2: No writer is a singer.
Statement 3: Some singers are actors.
Conclusion I: No poet is a singer.
Conclusion II: Some actors are not writers.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Both conclusions follow", "Neither conclusion follows"]', 2, 'Poets are writers and no writer is a singer, so no poet is a singer (I). The actors who are singers cannot be writers, so some actors are not writers (II). Both follow.', '{"0": "Conclusion II also follows through the singer-actors.", "1": "Conclusion I also follows, because every poet is a writer.", "3": "Both conclusions follow."}'),
  ('LR-0342', 'Logical Reasoning', 'Logical deductions', 'Syllogisms', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Statement 1: All circles are shapes.
Statement 2: Some shapes are squares.
Conclusion I: Some circles are squares.
Conclusion II: No circle is a square.
Which conclusion(s) logically follow?', '["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither conclusion follows"]', 2, 'Nothing fixes whether circles and squares overlap, so neither conclusion is certain alone. But ''some circles are squares'' and ''no circle is a square'' cannot both be false, and cannot both be true, so either I or II follows.', '{"0": "Conclusion I is not certain on its own.", "1": "Conclusion II is not certain on its own.", "3": "I and II form a complementary pair, so one of them must hold."}'),
  ('LR-0343', 'Logical Reasoning', 'Logical deductions', 'Coded relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'P + Q means P is the son of Q.
P − Q means P is the wife of Q.
P × Q means P is the brother of Q.
If A × B + C − D, how is A related to D?', '["Brother", "Son", "Nephew", "Grandson"]', 1, 'A × B: A is B''s brother. B + C: B is C''s son. C − D: C is D''s wife. So B is the son of C and D, and A, being B''s brother, is also D''s son.', '{"0": "D is a parent of A''s brother, so A is D''s child, not brother.", "2": "A nephew would be a sibling''s child; D is A''s parent.", "3": "A is only one generation below D."}'),
  ('LR-0344', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Pointing to a man, Hina says, "He is the only son of my mother''s father-in-law''s only son." How is the man related to Hina?', '["Father", "Cousin", "Brother", "Uncle"]', 2, 'Hina''s mother''s father-in-law is Hina''s paternal grandfather. His only son is Hina''s father. The only son of Hina''s father is Hina''s brother.', '{"0": "Hina''s father is the grandfather''s only son; the man is the son of that person.", "1": "A cousin would be a child of an uncle or aunt, but the grandfather has only one son, Hina''s father.", "3": "An uncle would be another son of the grandfather, but he has only one."}'),
  ('LR-0345', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'A''s father is B''s son. C is B''s only daughter, and D is C''s husband. How is D related to A?', '["Father", "Grandfather", "Brother-in-law", "Uncle (father''s sister''s husband)"]', 3, 'A''s father is B''s son, so B is A''s grandparent. C, B''s daughter, is the sister of A''s father, so C is A''s aunt (phuppo). D, her husband, is A''s uncle (phupha).', '{"0": "A''s father is B''s son, not C''s husband.", "1": "B is the grandparent; D married into the family at the parents'' generation.", "2": "A brother-in-law is a sibling''s spouse or spouse''s sibling; D is one generation above A."}'),
  ('LR-0346', 'Logical Reasoning', 'Logical deductions', 'Blood relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'P is the grandfather of S. S is the daughter of R, and R is the only son of P. Q is P''s wife and the mother of R. T is R''s wife. How is T related to Q?', '["Daughter-in-law", "Daughter", "Sister-in-law", "Granddaughter"]', 0, 'R is Q''s son, and T is R''s wife, so T is Q''s daughter-in-law.', '{"1": "T married into the family; she is not Q''s own child.", "2": "A sister-in-law would be at Q''s own generation.", "3": "S, not T, is the granddaughter."}'),
  ('LR-0347', 'Logical Reasoning', 'Logical deductions', 'Coded relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'A $ B means A is the father of B.
A # B means A is the sister of B.
A @ B means A is the husband of B.
If P $ Q # R @ S, how is S related to P?', '["Daughter", "Daughter-in-law", "Wife", "Sister"]', 1, 'P is Q''s father. Q is R''s sister, so R is also P''s child; R is male because he is S''s husband. S, the wife of P''s son R, is P''s daughter-in-law.', '{"0": "Q is P''s daughter; S married into the family.", "2": "S is R''s wife, not P''s.", "3": "S is one generation below P."}'),
  ('LR-0348', 'Logical Reasoning', 'Logical deductions', 'Coded relations', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'A ★ B means A is the brother of B.
A ◆ B means A is the mother of B.
A ▲ B means A is the son of B.
If M ◆ N ★ O ▲ P, how is P related to M?', '["Son", "Father", "Husband", "Brother"]', 2, 'M is N''s mother. N is O''s brother, so M is also O''s mother. O is P''s son, and since M is O''s mother, P must be O''s father, which makes P M''s husband.', '{"0": "O, not P, is M''s son.", "1": "P is at the same generation as M.", "3": "P is the father of M''s children, so P is M''s husband."}'),
  ('LR-0349', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'In a row, A is 15th from the left and B is 20th from the right. When they swap places, A becomes 25th from the left. How many people are in the row?', '["45", "40", "35", "44"]', 3, 'After the swap A takes B''s old place, so B''s place was 25th from the left and 20th from the right. Total = 25 + 20 − 1 = 44.', '{"0": "45 forgets that B''s place is counted twice.", "1": "40 subtracts 5, not 1.", "2": "35 adds 15 and 20, using A''s old place."}'),
  ('LR-0350', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'In a class of 45 students, Rahim ranks 14th from the top. Saad is 7 ranks below Rahim. What is Saad''s rank from the bottom?', '["25th", "24th", "21st", "32nd"]', 0, 'Saad is 14 + 7 = 21st from the top. From the bottom he is 45 − 21 + 1 = 25th.', '{"1": "24th forgets to add 1.", "2": "21st is his rank from the top.", "3": "32nd is 45 − 14 + 1, Rahim''s rank from the bottom."}'),
  ('LR-0351', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'R is older than S. T is older than S. U is younger than R but older than T. Who is the oldest?', '["T", "R", "U", "Cannot be determined"]', 1, 'U is younger than R and older than T, so R > U > T, and T > S. R is the oldest.', '{"0": "T is younger than U.", "2": "U is younger than R.", "3": "The statement about U fixes R above T, so the oldest is known."}'),
  ('LR-0352', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Five students A, B, C, D and E each scored differently. A scored more than B and C. D scored less than C but more than B. E scored the least. Who scored the second lowest?', '["D", "C", "B", "E"]', 2, 'From the statements: A > C > D > B, and E is the lowest. The order is A, C, D, B, E, so B is second lowest.', '{"0": "D is above B.", "1": "C is second highest.", "3": "E is the lowest, not second lowest."}'),
  ('LR-0353', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'In a row of children, Rida is 9th from the left and Uzma is 16th from the right. There are exactly 4 children between them. How many children could be in the row?', '["29 only", "19 only", "28 or 30", "19 or 29"]', 3, 'If Uzma is to Rida''s right, she is 9 + 5 = 14th from the left, so the row has 14 + 16 − 1 = 29. If she is to Rida''s left, she is 9 − 5 = 4th from the left, giving 4 + 16 − 1 = 19. Both are possible.', '{"0": "This assumes Uzma is to Rida''s right.", "1": "This assumes Uzma is to Rida''s left.", "2": "These come from counting the 4 children wrongly."}'),
  ('LR-0354', 'Logical Reasoning', 'Logical deductions', 'Ranking', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'M is heavier than N. O is heavier than N. P is lighter than N. Who is the heaviest?', '["Cannot be determined", "M", "O", "N"]', 0, 'Both M and O are heavier than N, but nothing compares M with O. Either could be the heaviest.', '{"1": "M might be lighter than O.", "2": "O might be lighter than M.", "3": "N is lighter than both M and O."}'),
  ('LR-0355', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'If the generator is on, the lights work. If the lights work, the guard stays awake. The guard fell asleep.
Which must be true?', '["The lights worked", "The generator was off", "The generator was on", "The lights failed but the generator was on"]', 1, 'Guard asleep means the lights did not work (from the second rule). Lights not working means the generator was not on (from the first rule).', '{"0": "If the lights had worked, the guard would have stayed awake.", "2": "If it had been on, the lights would have worked and the guard stayed awake.", "3": "If the generator had been on, the lights would have worked."}'),
  ('LR-0356', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', '"Unless it rains, the match will be played." The match was not played.
Which conclusion follows?', '["It did not rain", "The match was cancelled for some other reason", "It rained", "Nothing can be concluded"]', 2, '''Unless it rains, the match will be played'' means ''if it does not rain, the match is played''. The match was not played, so it must have rained (otherwise it would have gone ahead).', '{"0": "If it had not rained, the match would have been played.", "1": "The statement says the match is played whenever it does not rain, which rules out other reasons on a dry day.", "3": "The contrapositive gives a definite conclusion."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0357', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'If Ali goes on the trip, Bilal goes. If Bilal goes, Chand does not go. Chand goes.
Which must be true?', '["Ali goes", "Bilal goes", "Ali and Bilal both go", "Ali does not go"]', 3, 'Chand goes, so Bilal cannot go (if Bilal went, Chand would not). Bilal not going means Ali cannot go (if Ali went, Bilal would).', '{"0": "If Ali went, Bilal would go, and then Chand could not.", "1": "If Bilal went, Chand would not go.", "2": "Neither of them can go."}'),
  ('LR-0358', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', '"Only students who pass the test get a certificate." Sara got a certificate.
Which must be true?', '["Sara passed the test", "Everyone who passed got a certificate", "Sara got the highest marks", "Some students who failed got a certificate"]', 0, '''Only those who pass get a certificate'' means passing is necessary for a certificate. Sara has one, so she passed.', '{"1": "Passing is necessary, not sufficient; some who passed may get none.", "2": "Nothing is said about marks.", "3": "This contradicts the statement."}'),
  ('LR-0359', 'Logical Reasoning', 'Logical deductions', 'Conditional reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'If a test is easy, more than half the class passes it. In the last test, fewer than half the class passed.
Which conclusion follows?', '["The test was easy", "The test was not easy", "The students did not prepare", "Nothing can be concluded"]', 1, 'An easy test would mean more than half passed. Fewer than half passed, so the test was not easy (contrapositive).', '{"0": "If it had been easy, more than half would have passed.", "2": "Preparation is not mentioned in the rule.", "3": "The contrapositive gives a definite conclusion."}'),
  ('LR-0360', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Every member of the club is a student. Some students are athletes. No athlete smokes.
Which statement is definitely FALSE?', '["Some club members are athletes", "No club member smokes", "All students smoke", "Some students do not smoke"]', 2, 'Some students are athletes, and athletes do not smoke, so at least some students do not smoke. ''All students smoke'' contradicts this.', '{"0": "This might be true or false; it is not certainly false.", "1": "This might be true or false; it is not certainly false.", "3": "This is definitely true, not false."}'),
  ('LR-0361', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.2', 'Five clinics A, B, C, D and E each open on a different weekday from Monday to Friday.
A opens earlier in the week than C.
B opens on Wednesday.
E opens the day after D.
C does not open on Friday.
Which clinic opens on Tuesday?', '["A", "D", "E", "C"]', 3, 'D and E are on consecutive days, so they are Monday–Tuesday or Thursday–Friday. If D–E took Monday–Tuesday, A and C would take Thursday–Friday with C on Friday, which is not allowed. So D is Thursday, E Friday, A Monday and C Tuesday.', '{"0": "A is on Monday.", "1": "D is on Thursday.", "2": "E is on Friday."}'),
  ('LR-0362', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Some students who study at night score well. Everyone who scores well gets a scholarship.
Which must be true?', '["Some students who study at night get a scholarship", "All students who study at night get a scholarship", "Everyone with a scholarship studies at night", "Students who study in the day never get a scholarship"]', 0, 'The night-studiers who score well are among those who score well, and all of those get a scholarship. So some night-studiers get one.', '{"1": "Only some night-studiers score well.", "2": "This reverses the second statement.", "3": "Nothing is said about day-studiers."}'),
  ('LR-0363', 'Logical Reasoning', 'Logical deductions', 'Statements and conclusions', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.3.1', 'Every shirt in a shop is either cotton or silk, not both. Every silk shirt is expensive. No cotton shirt has buttons. One shirt in the shop has buttons.
Which must be true about that shirt?', '["It is cotton", "It is expensive", "It is cheap", "It is both cotton and silk"]', 1, 'No cotton shirt has buttons, so the buttoned shirt is not cotton. It must therefore be silk, and every silk shirt is expensive.', '{"0": "Cotton shirts have no buttons.", "2": "It is silk, and silk shirts are expensive.", "3": "A shirt cannot be both."}'),
  ('LR-0364', 'Logical Reasoning', 'Logical problems', 'Using one result to solve another', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', '5 machines make 5 parts in 5 minutes. Using the same rate, how long would 100 machines take to make 100 parts?', '["5 minutes", "100 minutes", "20 minutes", "1 minute"]', 0, 'From the first fact, one machine makes one part in 5 minutes. So 100 machines working side by side make 100 parts in the same 5 minutes.', '{"1": "100 minutes assumes one machine makes all the parts.", "2": "20 minutes scales the time by 100 ÷ 5 without reason.", "3": "1 minute assumes more machines make each part faster."}'),
  ('LR-0365', 'Logical Reasoning', 'Logical problems', 'Using one result to solve another', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'A snail at the bottom of a 10 m well climbs 3 m every day and slips back 2 m every night. On which day does it get out?', '["10th day", "8th day", "7th day", "9th day"]', 1, 'Each full day-and-night it gains 1 m. After 7 days and nights it is at 7 m. On the 8th day it climbs 3 m to reach 10 m and is out before it can slip back.', '{"0": "10 days ignores that on the last day it does not slip back.", "2": "On the 7th day it reaches only 9 m and slips back to 7 m that night.", "3": "On the 8th day it already reaches the top."}'),
  ('LR-0366', 'Logical Reasoning', 'Logical problems', 'Using one result to solve another', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'It takes 6 minutes to cut a log into 3 pieces. At the same rate, how long will it take to cut the same kind of log into 6 pieces?', '["12 minutes", "18 minutes", "15 minutes", "10 minutes"]', 2, '3 pieces need 2 cuts, so each cut takes 3 minutes. 6 pieces need 5 cuts: 5 × 3 = 15 minutes.', '{"0": "12 minutes doubles the time, as if 6 pieces needed twice as many cuts as 3 pieces.", "1": "18 minutes assumes one cut per piece.", "3": "10 minutes uses 2 minutes per cut."}'),
  ('LR-0367', 'Logical Reasoning', 'Logical problems', 'Using one result to solve another', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'Three days after the day before yesterday is Friday. What day is today?', '["Wednesday", "Friday", "Tuesday", "Thursday"]', 3, '''The day before yesterday'' is today − 2. Three days after that is today + 1, which is Friday. So today is Thursday.', '{"0": "Wednesday would make three days after the day before yesterday a Thursday.", "1": "Friday is tomorrow, not today.", "2": "Tuesday is the day before yesterday."}'),
  ('LR-0368', 'Logical Reasoning', 'Logical problems', 'Input and output', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'A machine doubles any number fed into it and then subtracts 3. A number is passed through the machine, and the result is passed through it again. The final output is 31.
What number was fed in first?', '["10", "17", "8.5", "12"]', 0, 'Work backwards. Before the second pass: (31 + 3) ÷ 2 = 17. Before the first pass: (17 + 3) ÷ 2 = 10.', '{"1": "17 is the number after the first pass, not the starting number.", "2": "8.5 halves 17 but forgets to add 3 first.", "3": "12 does not give 31 (12 → 21 → 39)."}'),
  ('LR-0369', 'Logical Reasoning', 'Logical problems', 'Cubes and dice', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'On a standard die, the numbers on opposite faces add up to 7. Which number can never be on a face next to (touching) the face showing 4?', '["1", "3", "5", "6"]', 1, 'The face opposite 4 shows 7 − 4 = 3. Opposite faces never touch, so 3 is never next to 4; all other numbers are.', '{"0": "1 is opposite 6, so it touches 4.", "2": "5 is opposite 2, so it touches 4.", "3": "6 is opposite 1, so it touches 4."}'),
  ('LR-0370', 'Logical Reasoning', 'Logical problems', 'Cubes and dice', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A 3 cm cube is painted on all faces and cut into 1 cm cubes. How many small cubes have NO paint on them?', '["0", "6", "1", "8"]', 2, 'Only the cube at the very centre has no face on the outside: (3 − 2)³ = 1.', '{"0": "The central cube is hidden from every face.", "1": "6 is the number of cubes with exactly one painted face (face centres).", "3": "8 is the number of corner cubes, with three painted faces."}'),
  ('LR-0371', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Ali, Bina, Chand and Dua each study a different subject: Biology, Chemistry, Physics or English.
Ali does not study a science.
Bina studies neither Physics nor Biology.
Dua does not study Biology.
Who studies Physics?', '["Bina", "Chand", "Ali", "Dua"]', 3, 'Ali does not study a science, so Ali studies English. Bina can then only study Chemistry. Dua cannot take Biology, so Dua studies Physics, leaving Biology for Chand.', '{"0": "Bina studies Chemistry.", "1": "Chand studies Biology.", "2": "Ali studies English."}'),
  ('LR-0372', 'Logical Reasoning', 'Logical problems', 'Seating arrangement', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Seven friends P, Q, R, S, T, U and V sit in a row facing north.
S sits exactly in the middle.
P and U sit at the two ends.
Exactly one person sits between Q and P.
R and T sit next to each other.
V sits somewhere to the right of S, and T sits somewhere to the left of S.
Who sits second from the right end?', '["V", "Q", "P", "R"]', 0, 'If P were at the left end, Q would be 3rd from the left, leaving T only the 2nd seat with no free seat beside it for R. So P is at the right end and U at the left end. Q is then 3rd from the right, V (right of S) takes the only free seat on the right, 2nd from the right, and R and T fill seats 2 and 3 from the left (in either order).', '{"1": "Q is 3rd from the right, next to S.", "2": "P is at the right end itself.", "3": "R sits to the left of S."}'),
  ('LR-0373', 'Logical Reasoning', 'Logical problems', 'Truth and lies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'One of four students broke a window. Exactly ONE of them is telling the truth.
A: "B did it."
B: "D did it."
C: "I did not do it."
D: "B is lying."
Who broke the window?', '["A", "C", "B", "D"]', 1, 'B and D contradict each other, so exactly one of them is truthful, and that uses up the one true statement. So A and C are both lying. C lying means C did it. Check: A (''B did it'') is false and B (''D did it'') is false, so D is the one telling the truth.', '{"0": "If A did it, C (''I did not do it'') and D would both be telling the truth.", "2": "If B did it, A, C and D would all be telling the truth.", "3": "If D did it, B and C would both be telling the truth."}'),
  ('LR-0374', 'Logical Reasoning', 'Logical problems', 'Truth and lies', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'On an island, knights always tell the truth and knaves always lie.
A says: "B is a knave."
B says: "A and I are the same type."
What are A and B?', '["Both are knights", "Both are knaves", "A is a knight and B is a knave", "A is a knave and B is a knight"]', 2, 'If A is a knight, B is a knave, and B''s claim that they are the same type is false, as a knave''s should be: consistent. If A were a knave, B would be a knight, but then B''s true statement would make them the same type, which is a contradiction.', '{"0": "If both were knights, A''s statement that B is a knave would be false.", "1": "If both were knaves, B''s statement ''we are the same type'' would be true, which a knave cannot say.", "3": "Then B, a knight, would be saying something false (they are different types)."}'),
  ('LR-0375', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'On what day of the week did 14 August 1947 fall?', '["Friday", "Wednesday", "Sunday", "Thursday"]', 3, 'Count odd days: 1600 years give 0, the next 300 years give 1, and 1901–1946 (46 years with 11 leap years) give 46 + 11 = 57 → 1 odd day. From 1 January to 14 August 1947: 31+28+31+30+31+30+31+14 = 226 days → 226 mod 7 = 2. Total = 0 + 1 + 1 + 2 = 4 odd days, which is Thursday (0 = Sunday).', '{"0": "Friday is one odd day too many.", "1": "Wednesday is one odd day too few.", "2": "Sunday would mean 0 odd days."}'),
  ('LR-0376', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', '15 August 2025 is a Friday. What day of the week will 15 August 2027 be?', '["Sunday", "Saturday", "Monday", "Friday"]', 0, 'Neither period crosses a 29 February (2026 and 2027 are not leap years), so each year moves the day forward by 1. Two years later the day is Friday + 2 = Sunday.', '{"1": "Saturday adds only one year''s shift.", "2": "Monday adds three days, as if a leap day were included.", "3": "The day of the week changes each year."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0377', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Today is Thursday. What day of the week will it be 250 days from today?', '["Monday", "Tuesday", "Wednesday", "Thursday"]', 1, '250 = 35 weeks (245 days) + 5 days. Five days after Thursday is Tuesday.', '{"0": "Monday adds only 4 extra days.", "2": "Wednesday adds 6 extra days.", "3": "250 is not a multiple of 7, so the day changes."}'),
  ('LR-0378', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'The calendar of the year 2021 (exactly the same dates on the same days) can be used again in which year?', '["2025", "2032", "2027", "2029"]', 2, 'A calendar repeats when the year starts on the same day and has the same number of days. 2021 started on a Friday. Adding odd days: 2021 (1), 2022 (1), 2023 (1), 2024 (2), 2025 (1), 2026 (1) = 7, a whole week. So 2027 starts on Friday and is not a leap year.', '{"0": "2025 starts on a Wednesday.", "1": "2032 is a leap year, so it cannot match a 365-day year.", "3": "2029 starts on a Monday."}'),
  ('LR-0379', 'Logical Reasoning', 'Logical problems', 'Calendar problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'What is the greatest number of Sundays possible in a year that is not a leap year?', '["52", "54", "51", "53"]', 3, 'A non-leap year has 365 days = 52 weeks + 1 day. If that extra day is a Sunday (the year starts on a Sunday), the year has 53 Sundays.', '{"0": "52 is the minimum, not the maximum.", "1": "That would need at least 2 extra Sundays beyond 52 weeks.", "2": "Every year has at least 52 Sundays."}'),
  ('LR-0380', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'What is the smaller angle between the hour hand and the minute hand of a clock at 7:20?', '["100°", "90°", "110°", "80°"]', 0, 'Angle = |30 × hours − 5.5 × minutes| = |210 − 110| = 100°. (The hour hand has moved 10° past 7 in 20 minutes.)', '{"1": "90° treats the hour hand as still pointing exactly at 7; it moves 10° in 20 minutes.", "2": "110° moves the hour hand 20° instead of 10°.", "3": "80° moves the hour hand backwards instead of forwards."}'),
  ('LR-0381', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'At what time between 4 and 5 o''clock are the hour and minute hands exactly together?', '["20 minutes past 4", "21 9/11 minutes past 4", "22 minutes past 4", "21 3/11 minutes past 4"]', 1, 'At 4:00 the hour hand is 120° ahead. The minute hand gains 5.5° per minute, so it catches up after 120 ÷ 5.5 = 240/11 = 21 9/11 minutes.', '{"0": "At 4:20 the hour hand has moved 10° past 4, so the hands are 10° apart.", "2": "At 4:22 the minute hand has already passed the hour hand.", "3": "This miscalculates 240 ÷ 11."}'),
  ('LR-0382', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A clock is seen in a mirror and appears to show 3:40. What is the actual time?', '["9:20", "8:40", "8:20", "4:20"]', 2, 'For a mirror image, actual time = 11:60 − mirror time. 11:60 − 3:40 = 8:20.', '{"0": "9:20 subtracts from 12:60.", "1": "8:40 keeps the minutes unchanged.", "3": "4:20 mirrors only the minute hand."}'),
  ('LR-0383', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'How many times in one full day (24 hours) are the hands of a clock at right angles?', '["48", "24", "22", "44"]', 3, 'In 12 hours the hands are at right angles 22 times (twice an hour, except around 3 and 9 o''clock where one occurrence is shared). In 24 hours that is 44.', '{"0": "48 assumes exactly twice every hour.", "1": "24 assumes once an hour.", "2": "22 is the count for 12 hours only."}'),
  ('LR-0384', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A clock is set right at 8:00 am. It gains 5 minutes every hour. What will it show when the correct time is 2:00 pm the same day?', '["2:30 pm", "2:05 pm", "2:25 pm", "1:30 pm"]', 0, 'From 8 am to 2 pm is 6 hours. Gaining 5 minutes an hour, the clock is 30 minutes fast, so it shows 2:30 pm.', '{"1": "This adds the gain for one hour only.", "2": "This counts 5 hours instead of 6.", "3": "A clock that gains runs ahead, not behind."}'),
  ('LR-0385', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A grid has 3 rows and 4 columns of small squares. How many rectangles of all sizes (squares included) can be found in it?', '["12", "60", "20", "72"]', 1, 'A rectangle is fixed by choosing 2 of the 4 horizontal lines and 2 of the 5 vertical lines: C(4,2) × C(5,2) = 6 × 10 = 60.', '{"0": "12 counts only the smallest squares.", "2": "20 counts only the squares of all sizes (12 + 6 + 2).", "3": "72 miscounts the number of lines."}'),
  ('LR-0386', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'At a meeting, every person shook hands exactly once with every other person. There were 45 handshakes in all. How many people were at the meeting?', '["9", "15", "10", "45"]', 2, 'With n people there are n(n − 1) ÷ 2 handshakes. n(n − 1) = 90 gives n = 10.', '{"0": "9 people make only 36 handshakes.", "1": "15 people would make 105 handshakes.", "3": "45 is the number of handshakes, not people."}'),
  ('LR-0387', 'Logical Reasoning', 'Logical problems', 'Cubes', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A 4 cm cube is painted red on all faces and then cut into 1 cm cubes. How many small cubes have paint on exactly two faces?', '["8", "12", "32", "24"]', 3, 'Cubes with exactly two painted faces lie along the edges, not at the corners. Each of the 12 edges has 4 − 2 = 2 such cubes, so 12 × 2 = 24.', '{"0": "8 is the number of corner cubes, which have three painted faces.", "1": "12 allows only one cube per edge.", "2": "32 includes the corner cubes as well."}'),
  ('LR-0388', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A polygon has exactly 20 diagonals. How many sides does it have?', '["8", "10", "7", "20"]', 0, 'A polygon with n sides has n(n − 3) ÷ 2 diagonals. n(n − 3) = 40 gives n = 8 (8 × 5 = 40).', '{"1": "A 10-sided polygon has 35 diagonals.", "2": "A 7-sided polygon has 14 diagonals.", "3": "A 20-sided polygon has 170 diagonals."}'),
  ('LR-0389', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Eight points lie on a circle. How many different triangles can be drawn using these points as corners?', '["24", "56", "336", "28"]', 1, 'No three points on a circle are in a straight line, so any 3 points make a triangle: C(8, 3) = 56.', '{"0": "24 is 8 × 3, which is not a count of choices.", "2": "336 = 8 × 7 × 6 counts the same triangle in every order.", "3": "28 = C(8, 2) counts lines, not triangles."}'),
  ('LR-0390', 'Logical Reasoning', 'Logical problems', 'Counting problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'How many three-digit numbers have all three digits different?', '["720", "900", "648", "504"]', 2, 'The first digit can be 1–9 (9 ways), the second any of the remaining 9 digits (including 0), and the third any of the remaining 8: 9 × 9 × 8 = 648.', '{"0": "720 = 10 × 9 × 8 allows 0 as the first digit.", "1": "900 counts all three-digit numbers, repeats included.", "3": "504 = 9 × 8 × 7 wrongly excludes 0 from the later digits."}'),
  ('LR-0391', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Bilal walks 10 m north, turns right and walks 6 m, turns right again and walks 18 m, then turns left and walks 2 m.
How far is he from the start, and in which direction?', '["8 m south", "16 m south-east", "About 11.3 m north-east", "About 11.3 m (8√2 m) south-east"]', 3, 'Track east–west: 6 + 2 = 8 m east. North–south: 10 north − 18 south = 8 m south. He is 8 m east and 8 m south, so the distance is √(8² + 8²) = 8√2 ≈ 11.3 m, to the south-east.', '{"0": "This ignores the 8 m he has moved east.", "1": "16 m adds the two 8 m parts instead of using Pythagoras.", "2": "He ends up south of the start, not north."}'),
  ('LR-0392', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Early in the morning, Asif stands in an open field and notices that his shadow falls exactly to his right. Which direction is he facing?', '["South", "North", "East", "West"]', 0, 'In the morning the sun is in the east, so shadows point west. If west is on his right, he is facing south.', '{"1": "Facing north, west would be on his left.", "2": "Facing east, his shadow would fall behind him.", "3": "Facing west, his shadow would fall in front of him."}'),
  ('LR-0393', 'Logical Reasoning', 'Logical problems', 'Direction problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A man faces north. He turns 90° clockwise, then 135° anticlockwise, then 180°. Which direction does he now face?', '["North-west", "South-east", "South-west", "North-east"]', 1, 'North → 90° clockwise → east. 135° anticlockwise from east → north-west. 180° from north-west → south-east.', '{"0": "North-west is where he faces before the final 180° turn.", "2": "South-west is where he would face before the last turn if the 135° turn were made clockwise.", "3": "North-east comes from making the 135° turn clockwise instead of anticlockwise."}'),
  ('LR-0394', 'Logical Reasoning', 'Logical problems', 'Age problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'The ratio of A''s age to B''s age is 3 : 5. After 8 years the ratio will be 5 : 7. How old is A now?', '["15 years", "20 years", "12 years", "9 years"]', 2, 'Let the ages be 3x and 5x. Then (3x + 8) ÷ (5x + 8) = 5 ÷ 7, so 21x + 56 = 25x + 40 and x = 4. A is 3 × 4 = 12.', '{"0": "15 would give 23 : 33 after 8 years, not 5 : 7.", "1": "20 is B''s age.", "3": "9 would give 17 : 23 after 8 years."}'),
  ('LR-0395', 'Logical Reasoning', 'Logical problems', 'Percentages', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'The price of a book is raised by 20% and later lowered by 20%. What is the overall change in price?', '["No change", "A 4% increase", "A 2% decrease", "A 4% decrease"]', 3, 'Take Rs 100: +20% gives 120, then −20% of 120 = 24, giving 96. That is a 4% fall overall.', '{"0": "The 20% cut is taken from a bigger amount, so it removes more than was added.", "1": "The final price is lower, not higher.", "2": "The fall is 20% of 20% = 4%, not 2%."}'),
  ('LR-0396', 'Logical Reasoning', 'Logical problems', 'Work and time', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'A can finish a job in 10 days and B can finish it in 15 days. Working together, how long will they take?', '["6 days", "12.5 days", "5 days", "25 days"]', 0, 'A does 1/10 of the job a day and B does 1/15. Together: 1/10 + 1/15 = 5/30 = 1/6 of the job a day, so 6 days.', '{"1": "12.5 is the average of 10 and 15; working together is faster than either alone.", "2": "5 days would need 1/5 of the job a day.", "3": "25 adds the times instead of the rates."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0397', 'Logical Reasoning', 'Logical problems', 'Speed and distance', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'A train 200 m long travels at 72 km/h. How long does it take to cross a bridge 300 m long completely?', '["15 seconds", "25 seconds", "10 seconds", "7 seconds"]', 1, '72 km/h = 20 m/s. To clear the bridge the train must cover the bridge plus its own length: 300 + 200 = 500 m. Time = 500 ÷ 20 = 25 s.', '{"0": "15 s uses only the bridge''s length.", "2": "10 s uses only the train''s length.", "3": "7 s divides 500 by 72 without converting units."}'),
  ('LR-0398', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'What is the smallest number of people you need in a room to be CERTAIN that at least two of them were born in the same month?', '["12", "2", "13", "24"]', 2, 'With 12 people, everyone could be born in a different month. The 13th person must share a month with someone (pigeonhole principle).', '{"0": "12 people could all have different months.", "1": "Two people could easily have different months.", "3": "24 makes it certain but is not the smallest number."}'),
  ('LR-0399', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A dark drawer holds 10 black socks and 10 white socks. What is the smallest number of socks you must take out, without looking, to be certain of getting two BLACK socks?', '["3", "11", "4", "12"]', 3, 'In the worst case you first pick all 10 white socks. You then need 2 more to be sure of two black: 10 + 2 = 12.', '{"0": "3 guarantees a matching pair of some colour, not two black socks.", "1": "11 could be 10 white and only 1 black.", "2": "4 could all be white."}'),
  ('LR-0400', 'Logical Reasoning', 'Logical problems', 'Sets and groups', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'In a group of 100 students, 50 study Biology, 40 Chemistry and 30 Physics. 15 study Biology and Chemistry, 10 Chemistry and Physics, 12 Biology and Physics, and 5 study all three.
How many study none of the three?', '["12", "17", "7", "0"]', 0, 'Students in at least one subject = 50 + 40 + 30 − 15 − 10 − 12 + 5 = 88. So 100 − 88 = 12 study none.', '{"1": "17 forgets to add back the 5 who study all three.", "2": "7 adds the 5 the wrong way.", "3": "Some students must be outside all three groups, since only 88 are in any."}'),
  ('LR-0401', 'Logical Reasoning', 'Logical problems', 'Sets and groups', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'In a group of 100 students, 50 study Biology, 40 Chemistry and 30 Physics. 15 study Biology and Chemistry, 10 Chemistry and Physics, 12 Biology and Physics, and 5 study all three.
How many study ONLY Biology?', '["23", "28", "33", "35"]', 1, 'Only Biology = 50 − 15 − 12 + 5 = 28. The 5 who take all three were subtracted twice (in both overlaps), so they are added back once.', '{"0": "23 does not add back the 5 taking all three.", "2": "33 adds the 5 back twice.", "3": "35 subtracts only the Biology–Chemistry overlap."}'),
  ('LR-0402', 'Logical Reasoning', 'Logical problems', 'Code language', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'In a code language:
"tea is hot" is written "la ra pa"
"hot milk is good" is written "pa sa ra ka"
"good tea" is written "ka la"
What is the code for "milk"?', '["ka", "pa", "sa", "ra"]', 2, '''tea'' is in sentences 1 and 3, whose only shared code is ''la'', so tea = la. ''good'' is in sentences 2 and 3, sharing only ''ka'', so good = ka. In sentence 2, ''hot'' and ''is'' take ''pa'' and ''ra'' (the codes shared with sentence 1), leaving milk = sa.', '{"0": "ka is ''good''.", "1": "pa is ''hot'' or ''is''.", "3": "ra is ''hot'' or ''is''."}'),
  ('LR-0403', 'Logical Reasoning', 'Logical problems', 'Code language', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.1', 'In a code language:
"pen is red" is written "dop tik mal"
"red ink dries" is written "sup mal ren"
"ink is blue" is written "ren tik zor"
Which word is written "dop"?', '["is", "red", "blue", "pen"]', 3, '''red'' is in sentences 1 and 2, which share only ''mal'', so red = mal. ''is'' is in sentences 1 and 3, which share only ''tik'', so is = tik. The remaining code in sentence 1, ''dop'', must be ''pen''.', '{"0": "''is'' is tik (shared by sentences 1 and 3).", "1": "''red'' is mal (shared by sentences 1 and 2).", "2": "''blue'' is zor; it does not appear in sentence 1."}'),
  ('LR-0404', 'Logical Reasoning', 'Logical problems', 'Ordering puzzles', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'A building has five floors, numbered 1 (bottom) to 5 (top). P, Q, R, S and T each live on a different floor.
T lives on the top floor.
Q lives directly above S.
R lives on an even-numbered floor.
P does not live on floor 1, and P lives directly above or below R.
Who lives on floor 1?', '["S", "R", "Q", "P"]', 0, 'T is on floor 5, so R (even) is on floor 2 or 4. If R were on 2, P (next to R, not on 1) would be on 3, leaving floors 1 and 4 for Q and S, which are not next to each other. So R is on 4 and P on 3. Q and S take floors 1 and 2 with Q above, so S is on floor 1.', '{"1": "R is on floor 4.", "2": "Q is on floor 2, directly above S.", "3": "P is on floor 3, and the clue says P is not on floor 1."}'),
  ('LR-0405', 'Logical Reasoning', 'Logical problems', 'Seating arrangement', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Six friends A, B, C, D, E and F sit around a round table, facing the centre.
B sits opposite E.
C sits immediately to A''s right.
F sits next to D.
F does not sit opposite A.
Who sits opposite A?', '["F", "D", "B", "C"]', 1, 'C is next to A, so C is not opposite A, and B and E sit opposite each other, so neither of them is opposite A either. That leaves D or F, and F is ruled out by the last clue. So D is opposite A (F sits beside D, and B and E take the remaining opposite pair).', '{"0": "The clue says F is not opposite A.", "2": "B is opposite E, not A.", "3": "C sits right next to A."}'),
  ('LR-0406', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Three closed boxes are labelled "Apples", "Oranges" and "Apples and oranges". Every label is WRONG. You may take out one fruit from one box without looking inside. From which box should you take it so that you can then label all three boxes correctly?', '["The box labelled \"Apples\"", "The box labelled \"Oranges\"", "The box labelled \"Apples and oranges\"", "It cannot be done with one fruit"]', 2, 'The box labelled ''Apples and oranges'' is wrongly labelled, so it holds only one kind of fruit; one fruit tells you which. Say it is an apple: that box is Apples. The box labelled ''Oranges'' cannot be oranges (wrong label) or apples (taken), so it is the mixed box, and the box labelled ''Apples'' is Oranges.', '{"0": "That box could be oranges or mixed; an orange drawn from it would not tell you which.", "1": "That box could be apples or mixed; an apple drawn from it would not tell you which.", "3": "Drawing from the box labelled ''Apples and oranges'' settles all three."}'),
  ('LR-0407', 'Logical Reasoning', 'Logical problems', 'Logical puzzles', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'Amna, Babar and Sana each study a different subject (Biology, Chemistry or Physics) and come from a different city (Lahore, Karachi or Quetta).
Amna does not study Biology.
Babar is from Karachi.
The Chemistry student is from Quetta.
The Physics student is not from Lahore.
Sana does not study Physics.
Who is from Lahore, and what does that person study?', '["Amna, Physics", "Sana, Chemistry", "Amna, Biology", "Sana, Biology"]', 3, 'The Physics student is not from Lahore and not from Quetta (that is the Chemistry student), so the Physics student is from Karachi: Babar. Sana does not study Physics, and Amna does not study Biology, so Amna studies Chemistry (Quetta) and Sana studies Biology (Lahore).', '{"0": "Babar, from Karachi, is the Physics student.", "1": "The Chemistry student is from Quetta, not Lahore.", "2": "Amna does not study Biology."}'),
  ('LR-0408', 'Logical Reasoning', 'Logical problems', 'Clock problems', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.4.2', 'How many times do the hour and minute hands of a clock point in exactly the same direction between 12 noon and 12 midnight, not counting noon and midnight themselves?', '["10", "11", "12", "22"]', 0, 'The minute hand gains a full lap on the hour hand every 12/11 hours, so in 12 hours the hands meet 11 times counting the meeting at noon (the meeting at midnight starts the next cycle). Leaving out noon gives 10. Notice there is no meeting between 11 and 12 o''clock except at 12 itself.', '{"1": "11 counts the meeting at noon or midnight.", "2": "12 assumes the hands meet once every hour.", "3": "22 is the number of meetings in a whole day."}'),
  ('LR-0409', 'Logical Reasoning', 'Course of action', 'Strong and weak arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.3', 'Statement: Should mobile phones be banned in exam halls?
Argument I: Yes. Phones can be used to cheat during the exam.
Argument II: No. Students may want to call their parents during the exam.
Which argument(s) are strong?', '["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"]', 0, 'Argument I is directly relevant and important: phones make cheating easy. Argument II is weak because students can call their parents before or after the exam.', '{"1": "Calling home can wait until the exam is over, so II is weak.", "2": "Argument II is weak.", "3": "Argument I gives a strong, relevant reason."}'),
  ('LR-0410', 'Logical Reasoning', 'Course of action', 'Strong and weak arguments', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.3', 'Statement: Should MDCAT be held twice a year?
Argument I: Yes. It would give students a second chance without losing a whole year.
Argument II: No. Two sittings would double the testing body''s costs and make it hard to keep both papers equally difficult.
Which argument(s) are strong?', '["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"]', 2, 'Both arguments raise real, important consequences: one a benefit to students, the other practical and fairness problems. Both are strong.', '{"0": "Argument II also raises a real, important concern.", "1": "Argument I also gives a real benefit.", "3": "Both arguments are relevant and important."}'),
  ('LR-0411', 'Logical Reasoning', 'Course of action', 'Strong and weak arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.3', 'Statement: Should junk food be sold in school canteens?
Argument I: No. It harms children''s health.
Argument II: Yes. Children like junk food.
Which argument(s) are strong?', '["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"]', 0, 'Harm to health is a serious, relevant reason. Children''s liking for junk food is not a strong reason to sell it in schools.', '{"1": "Liking something is not a strong reason when health is at stake.", "2": "Argument II is weak.", "3": "Argument I is strong."}'),
  ('LR-0412', 'Logical Reasoning', 'Course of action', 'Strong and weak arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.3', 'Statement: Should every student be required to learn swimming?
Argument I: Yes. All famous athletes can swim.
Argument II: No. Some students already know how to swim.
Which argument(s) are strong?', '["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"]', 3, 'Neither argument is strong. What famous athletes can do is irrelevant to ordinary students, and the fact that some students can already swim says nothing about whether the others should learn.', '{"0": "Famous athletes'' skills do not bear on all students.", "1": "Students who can already swim would simply meet the requirement; this does not argue against it.", "2": "Both arguments are weak."}'),
  ('LR-0413', 'Logical Reasoning', 'Course of action', 'Strong and weak arguments', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.3', 'Statement: Should the college library stay open 24 hours a day?
Argument I: Yes. The library has many books.
Argument II: No. Opening all night would need extra staff and security that the college cannot afford, while few students would use it then.
Which argument(s) are strong?', '["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"]', 1, 'Argument II gives real costs against little benefit. Argument I is weak: the number of books has nothing to do with the opening hours.', '{"0": "The number of books does not justify opening all night.", "2": "Argument I is weak.", "3": "Argument II is strong."}'),
  ('LR-0414', 'Logical Reasoning', 'Course of action', 'Strong and weak arguments', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.3', 'Statement: Should medical colleges admit students on MDCAT scores alone, ignoring FSc marks?
Argument I: Yes. MDCAT is the same test for every candidate, so it compares all of them fairly.
Argument II: No. FSc marks show a student''s work over two years, not just on one day.
Which argument(s) are strong?', '["Only argument I is strong", "Only argument II is strong", "Both I and II are strong", "Neither I nor II is strong"]', 2, 'Each argument points to a real strength of one measure: MDCAT''s uniformity and FSc''s long-term record. Both are strong.', '{"0": "Argument II is also a relevant, important point.", "1": "Argument I is also a relevant, important point.", "3": "Both arguments are strong."}'),
  ('LR-0415', 'Logical Reasoning', 'Course of action', 'Gathering information', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.1', 'A principal hears that food from the college canteen made some students ill. What should the principal do FIRST?', '["Close the canteen permanently", "Find out how many students fell ill, what they ate and when", "Dismiss the cook", "Ignore it until parents complain"]', 1, 'Before deciding anything, the principal needs the facts: who was ill, what they ate and when. That shows whether the canteen is really the cause.', '{"0": "Permanent closure before the facts are known is premature.", "2": "Blaming the cook without evidence is unfair.", "3": "Ignoring a possible health risk is irresponsible."}'),
  ('LR-0416', 'Logical Reasoning', 'Course of action', 'Gathering information', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.1', 'A health officer must decide where to open one new clinic in a district. Which information is MOST useful?', '["Which area has the most shops", "Where the officer''s own office is", "How many people live in each area and how far they are from the nearest existing clinic", "Which area has the newest roads"]', 2, 'The clinic should go where many people have poor access to care, so population and distance to existing clinics matter most.', '{"0": "Shops say little about health needs.", "1": "The officer''s convenience is not the point.", "3": "New roads alone do not show where care is needed."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0417', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Several children in a village fell ill after drinking water from a newly installed hand pump.
Course of action I: Health officials should test the pump''s water and stop its use until the results come.
Course of action II: All hand pumps in the province should be removed.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Testing and pausing use of the suspect pump directly protects the children and finds the cause. Removing every pump in the province is far out of proportion to one pump''s problem and would leave people without water.', '{"1": "Removing every pump in the province is an overreaction to a problem at one pump.", "2": "Course II is extreme and impractical.", "3": "Course I is a sensible, direct response."}'),
  ('LR-0418', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many MDCAT candidates complained that the answer key for two questions was wrong.
Course of action I: The testing body should have subject experts review those two questions and correct the key if needed.
Course of action II: The whole test should be cancelled and held again.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'A review of the two disputed questions fixes the problem fairly. Cancelling the whole test for two questions would punish every candidate and is out of proportion.', '{"1": "Cancelling the test is far too drastic for two disputed questions.", "2": "Course II is out of proportion.", "3": "Course I directly addresses the complaint."}'),
  ('LR-0419', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Dengue cases rose sharply in a city after the monsoon.
Course of action I: The city should run a campaign to remove standing water from homes and streets.
Course of action II: Hospitals should set aside extra beds and platelet-testing facilities for dengue patients.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Course I attacks the cause (mosquito breeding in standing water) and Course II deals with the patients already falling ill. Both are practical and needed.', '{"0": "Course II is also needed to treat the rising number of patients.", "1": "Course I is also needed to stop mosquitoes breeding.", "3": "Both courses are practical responses to the problem."}'),
  ('LR-0420', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A busy bridge has developed visible cracks.
Course of action I: The bridge should be closed to heavy vehicles until engineers inspect it.
Course of action II: The engineer who designed the bridge should be jailed.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Limiting heavy traffic until an inspection protects lives. Jailing the designer before any inquiry assumes blame without evidence and does nothing to make the bridge safe.', '{"1": "Punishing someone before an inquiry is unjustified and does not fix the bridge.", "2": "Course II is not justified.", "3": "Course I is a sensible safety step."}'),
  ('LR-0421', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A survey shows that most students of a college skip breakfast.
Course of action I: The college should make breakfast compulsory and punish students who skip it.
Course of action II: The college should tell students why breakfast matters and offer affordable breakfast in the canteen.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Education plus an easy, cheap option tackles the reasons students skip breakfast. Punishing students for a personal eating habit is extreme and impractical.', '{"0": "Punishment for skipping a meal is extreme and hard to enforce.", "2": "Course I is not practical.", "3": "Course II is a practical way to help."}'),
  ('LR-0422', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A pharmacy chain''s sales fell after a new competitor opened nearby.
Course of action I: The chain should close all its branches.
Course of action II: The government should stop the competitor from operating.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'Neither course is sensible. Closing every branch over falling sales at one location is extreme, and stopping a lawful competitor is unfair and not the government''s role.', '{"0": "Closing every branch is an overreaction.", "1": "A lawful competitor cannot be shut down simply for competing.", "2": "Both courses are extreme."}'),
  ('LR-0423', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many patients at a government hospital wait more than five hours to see a doctor.
Course of action I: The hospital should introduce a token and appointment system.
Course of action II: The hospital should find out which departments have the longest queues and post extra staff there.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'An appointment system spreads patients over the day, and moving staff to the busiest departments shortens the queues where they are worst. Both are practical.', '{"0": "Course II is also a practical way to cut waiting times.", "1": "Course I is also practical and addresses the long waits.", "3": "Both courses address the problem."}'),
  ('LR-0424', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A student failed one subject in his first-term exam.
Course of action I: He should be expelled from the college.
Course of action II: He should drop all his other subjects and study only this one.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'Failing one subject in one term calls for extra help, not expulsion. Dropping every other subject would cause him to fail those instead.', '{"0": "Expulsion is far too harsh for one failed subject.", "1": "Dropping all other subjects creates a bigger problem.", "2": "Both courses are extreme."}'),
  ('LR-0425', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Air pollution in Lahore reaches dangerous levels every winter.
Course of action I: All schools in Lahore should be closed permanently.
Course of action II: Authorities should act against brick kilns and factories that break emission rules, especially in winter.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Enforcing emission rules reduces the pollution itself. Closing schools permanently is extreme; at most, temporary closures on the worst days might be considered.', '{"0": "Permanent closure of all schools is extreme and does not reduce pollution.", "2": "Course I is not justified.", "3": "Course II tackles a main source of the pollution."}'),
  ('LR-0426', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Reports say fake medicines are being sold in some rural markets.
Course of action I: Drug inspectors should raid suspect shops and test samples.
Course of action II: People should be taught how to check a medicine''s registration number and packaging.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Inspections remove fake medicines from sale, and public awareness helps buyers protect themselves. Each addresses the problem from a different side.', '{"0": "Course II also helps by making buyers more careful.", "1": "Course I is also needed to remove fakes from the market.", "3": "Both courses are practical and useful."}'),
  ('LR-0427', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A school''s science laboratory caught fire because of an electrical fault. Nobody was hurt.
Course of action I: The school should have all its electrical wiring checked by a qualified electrician.
Course of action II: The school should stop teaching science.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Checking the wiring prevents another fire anywhere in the school. Stopping science lessons does not address an electrical fault.', '{"1": "Stopping science lessons does not fix wiring.", "2": "Course II does not address the cause.", "3": "Course I deals directly with the cause."}'),
  ('LR-0428', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A rare bird is declining because farmers are draining its wetland habitat.
Course of action I: The wetland should be declared a protected area.
Course of action II: The government should pay nearby farmers to keep their land as wetland instead of draining it.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Protection stops further draining, and payments give farmers a reason to keep the wetland without losing income. Both address the cause of the decline.', '{"0": "Course II also tackles the cause by giving farmers an alternative.", "1": "Course I also protects the habitat directly.", "3": "Both courses address the loss of habitat."}'),
  ('LR-0429', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Road accidents involving motorcyclists without helmets have increased in the city.
Course of action I: The law requiring helmets should be strictly enforced.
Course of action II: Motorcycles should be banned in the city.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Enforcing the helmet law reduces serious injuries. Banning motorcycles would harm the many people who depend on them and is out of proportion.', '{"1": "A total ban is extreme and impractical.", "2": "Course II is not practical.", "3": "Course I directly addresses the problem."}'),
  ('LR-0430', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Some teachers at a college are often absent without informing anyone.
Course of action I: The college should set up a clear attendance record and leave procedure for teachers.
Course of action II: The principal should find out the reasons for these absences.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'A proper leave system makes absences visible and accountable, and finding the reasons may reveal problems the college can fix. Both are reasonable.', '{"0": "Course II is also useful to understand the causes.", "1": "Course I is also needed to control unreported absences.", "3": "Both courses are reasonable."}'),
  ('LR-0431', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A heat wave is forecast for the coming week.
Course of action I: The authorities should advise people to stay indoors at midday and drink plenty of water.
Course of action II: Hospitals should prepare to treat more cases of heatstroke.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Public advice prevents heatstroke, and hospital preparation deals with cases that still occur. Both follow.', '{"0": "Course II is also a sensible precaution.", "1": "Course I is also needed to prevent illness.", "3": "Both courses are practical."}'),
  ('LR-0432', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A college''s exam results have fallen for three years in a row.
Course of action I: The college should find out what has changed, such as staff, syllabus or teaching time.
Course of action II: The college should replace its entire teaching staff at once.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Finding the cause is the right first step. Replacing every teacher without knowing the cause is drastic and may not solve anything.', '{"1": "Replacing all staff before finding the cause is drastic.", "2": "Course II is premature.", "3": "Course I is the sensible first step."}'),
  ('LR-0433', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: An old building in the city centre has been declared unsafe, and families still live in it.
Course of action I: The families should be moved to a safe place.
Course of action II: Engineers should assess the building and it should then be repaired or demolished.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Moving the families protects lives now, and an assessment followed by repair or demolition deals with the building itself. Both follow.', '{"0": "Course II is also needed to deal with the building.", "1": "Course I is needed to protect the families now.", "3": "Both courses follow."}'),
  ('LR-0434', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A newspaper reported that a few students in a hostel had food poisoning.
Course of action I: The hostel kitchen should be inspected for hygiene.
Course of action II: The hostel should be shut down permanently.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Inspecting the kitchen finds and fixes the likely cause. Permanently closing the hostel over a few cases is extreme.', '{"1": "Permanent closure is far out of proportion.", "2": "Course II is extreme.", "3": "Course I addresses the likely cause."}'),
  ('LR-0435', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many young people in a district are unemployed even though they have degrees.
Course of action I: The government should offer job-skills training linked to local industries.
Course of action II: Universities in the district should stop awarding degrees.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'Training linked to local jobs helps graduates find work. Stopping degrees would make the situation worse, not better.', '{"1": "Stopping degrees does not create jobs.", "2": "Course II is harmful.", "3": "Course I is a practical step."}'),
  ('LR-0436', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: The water level in the city''s dam is much lower than usual before summer.
Course of action I: People should be encouraged to use water carefully.
Course of action II: Authorities should check the main supply pipes for leaks.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Careful use reduces demand, and fixing leaks stops water being wasted before it reaches homes. Both stretch the limited supply.', '{"0": "Course II also saves water.", "1": "Course I also saves water.", "3": "Both courses help conserve the limited supply."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0437', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many students find the new online admission portal confusing.
Course of action I: The portal should be scrapped and admissions made paper-only.
Course of action II: The admissions office should publish a simple step-by-step guide and run a helpline.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'A guide and helpline remove the confusion while keeping the benefits of online admission. Scrapping the portal is an overreaction.', '{"0": "Scrapping the whole system is an overreaction to confusion.", "2": "Course I is extreme.", "3": "Course II directly addresses the confusion."}'),
  ('LR-0438', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A medicine has been found to cause serious side effects in children.
Course of action I: The medicine should be banned for all patients worldwide immediately.
Course of action II: Doctors should be told not to prescribe it to children until a further review is done.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'The problem is in children, so stopping its use in children until review protects them. A worldwide ban for everyone goes beyond the evidence and may harm adults who benefit.', '{"0": "The evidence concerns children; a ban for all patients goes too far.", "2": "Course I goes beyond the evidence.", "3": "Course II directly protects children."}'),
  ('LR-0439', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Cheating was reported at a few centres during a board exam.
Course of action I: Every student in the province should retake the exam.
Course of action II: The cheating at those centres should be investigated and action taken against those involved.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Investigating the affected centres targets the problem. Making the whole province retake the exam punishes honest students everywhere.', '{"0": "A province-wide retake is out of proportion to cheating at a few centres.", "2": "Course I is unfair to most students.", "3": "Course II addresses the cheating directly."}'),
  ('LR-0440', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many trees on a university campus are dying of a fungal disease.
Course of action I: The university should cut down every tree on campus.
Course of action II: Experts should identify the disease and treat or remove the affected trees.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Diagnosing and treating or removing infected trees controls the disease. Cutting down healthy trees too is extreme.', '{"0": "Cutting down healthy trees is extreme.", "2": "Course I is not justified.", "3": "Course II targets the disease."}'),
  ('LR-0441', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A few passengers complained of rude behaviour by staff at a bus terminal.
Course of action I: All the terminal''s staff should be dismissed.
Course of action II: The terminal should be closed.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'A few complaints call for an inquiry and staff training, not mass dismissal or closing the terminal.', '{"0": "Dismissing all staff over a few complaints is extreme.", "1": "Closing the terminal punishes all passengers.", "2": "Both are extreme."}'),
  ('LR-0442', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: The price of a textbook has risen by 10%.
Course of action I: Students should stop buying textbooks.
Course of action II: The government should fix the price of every book in the country.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'A 10% rise in one book''s price does not justify giving up textbooks or price controls on every book in the country.', '{"0": "Students still need textbooks.", "1": "Price controls on all books are out of proportion to one price rise.", "2": "Both are extreme."}'),
  ('LR-0443', 'Logical Reasoning', 'Course of action', 'Courses of action', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A college''s cricket team lost its first match of the season.
Course of action I: The team should be disbanded.
Course of action II: The coach should be dismissed at once.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'One loss is normal in sport. Disbanding the team or firing the coach is a hasty overreaction.', '{"0": "Disbanding the team over one loss is extreme.", "1": "Dismissing the coach after one match is hasty.", "2": "Both are overreactions."}'),
  ('LR-0444', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Some patients say they would prefer evening clinic hours.
Course of action I: All clinics should open only in the evening.
Course of action II: Morning clinics should be closed.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 3, 'Only some patients want evening hours. Moving every clinic to evenings or closing morning clinics would harm the patients who use them now; adding some evening hours would be sensible instead.', '{"0": "Opening only in the evening ignores the patients who come in the morning.", "1": "Closing morning clinics harms current patients.", "2": "Both ignore the needs of other patients."}'),
  ('LR-0445', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many first-year medical students say anatomy is their hardest subject.
Course of action I: Anatomy should be removed from the course.
Course of action II: The college should offer extra tutorials and practical sessions in anatomy.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 1, 'Anatomy is essential for doctors, so removing it is not an option. Extra teaching helps students with the difficulty.', '{"0": "Anatomy is essential to medicine and cannot be dropped.", "2": "Course I is not acceptable.", "3": "Course II directly helps students."}'),
  ('LR-0446', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Several MDCAT candidates fainted at an exam centre where the hall had no working fans in hot weather.
Course of action I: Testing bodies should make sure exam halls are properly ventilated before exam day.
Course of action II: First-aid staff and drinking water should be available at every exam centre.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Ventilation prevents the cause, and first aid and water deal with anyone who still falls ill. Both follow.', '{"0": "Course II is also needed for candidates who still feel unwell.", "1": "Course I is needed to fix the cause.", "3": "Both are practical."}'),
  ('LR-0447', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: An inquiry found that a train accident was caused by a signalman who was working his third shift in a row.
Course of action I: The railways should set limits on how many hours signal staff can work without rest.
Course of action II: All trains in the country should stop running until every signalman is replaced.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'The cause was fatigue from excessive hours, so limiting continuous working hours directly prevents a repeat. Stopping all trains and replacing every signalman punishes everyone for one rota failure.', '{"1": "Halting the railway nationwide is out of proportion to the cause found.", "2": "Course II is extreme.", "3": "Course I addresses the cause identified by the inquiry."}'),
  ('LR-0448', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: A new study suggests that a widely used painkiller may slightly raise the risk of stomach bleeding in people who take it every day for years.
Course of action I: The drug regulator should review the evidence and, if it is confirmed, update the warning on the label.
Course of action II: Anyone who has taken the painkiller once for a headache should be told to go to hospital at once.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 0, 'The possible risk concerns long-term daily use and is not yet confirmed, so review and a label update are proportionate. Sending one-time users to hospital is unnecessary and would cause panic.', '{"1": "The risk concerns long-term users, not people who took a single dose.", "2": "Course II goes far beyond the evidence.", "3": "Course I is a proportionate response to new evidence."}'),
  ('LR-0449', 'Logical Reasoning', 'Course of action', 'Courses of action', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.5.2', 'Statement: Many students in rural areas cannot join online classes because they have no internet connection.
Course of action I: The government should improve internet access in rural areas.
Course of action II: Schools should give these students printed study packs and phone-based lessons in the meantime.
Which course(s) of action logically follow?', '["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"]', 2, 'Course I fixes the root problem over time, and Course II keeps students learning until it is fixed. Both are practical.', '{"0": "Course II is also needed, since better internet will take time.", "1": "Course I is needed to fix the underlying problem.", "3": "Both courses address the problem."}'),
  ('LR-0450', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'A visitor slipped and fell on a hospital corridor floor. Which is the most direct cause?', '["The floor had just been mopped and no warning sign was put up", "The hospital is very large", "Many visitors come in the evening", "The corridor is painted white"]', 0, 'A wet floor with no warning is a direct cause of slipping.', '{"1": "Size does not make a floor slippery.", "2": "Visiting time does not cause slipping.", "3": "Paint colour is irrelevant."}'),
  ('LR-0451', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Bread in a small bakery keeps going mouldy within two days. What is the most likely cause?', '["The bread is sold in paper bags", "The bread is stored in a warm, damp room", "The bakery opens early in the morning", "The bread is made with wheat flour"]', 1, 'Mould grows fastest in warm, moist conditions, so warm, damp storage is the most likely cause.', '{"0": "Paper bags let moisture escape; they do not cause rapid mould.", "2": "Opening hours do not affect mould.", "3": "Almost all bread is made with wheat flour."}'),
  ('LR-0452', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Several accidents happened at a crossing in one week. The traffic signal there had not worked all week. What most likely contributed to the accidents?', '["The crossing''s name", "The colour of the cars involved", "The broken traffic signal", "The day of the week"]', 2, 'Without a working signal, drivers do not know when to stop or go, so collisions become more likely.', '{"0": "A name does not affect traffic.", "1": "Car colour is irrelevant.", "3": "The accidents happened all week."}'),
  ('LR-0453', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'Some people say, "Cold weather gives you a cold." Which statement is more accurate?', '["Cold air itself turns into the cold virus", "Colds happen only in winter", "Wearing a sweater makes you immune to colds", "Colds are caused by viruses, not by cold air itself"]', 3, 'A cold is a viral infection. Cold weather may help the virus spread (for example, people crowd indoors together), but the cold air itself is not the cause.', '{"0": "Cold air cannot create a virus.", "1": "Colds also occur in other seasons.", "2": "Clothing does not give immunity."}'),
  ('LR-0454', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'Kashif believes that using his ''lucky pen'' improves his test marks. What is the best way to test this belief?', '["Compare his marks over many tests taken with and without the pen, under similar conditions", "Ask his friends what they think", "Use the pen once and see what happens", "Buy a more expensive pen"]', 0, 'A fair comparison over many tests is the only way to see whether the pen makes any real difference.', '{"1": "Opinions are not evidence.", "2": "One test is too few to show a pattern.", "3": "This does not test the belief at all."}'),
  ('LR-0455', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'A villager says the crops failed because a black cat crossed the field. An agriculture officer finds that the field received almost no water during the growing season.
What is the most reasonable conclusion?', '["The black cat and the drought caused it equally", "Lack of water is the likely cause, and the black cat story is a false belief", "The officer must be wrong", "Black cats bring bad luck to crops"]', 1, 'Crops need water; a season without water explains the failure. A cat crossing a field has no way of harming crops.', '{"0": "A cat has no effect on crops.", "2": "The officer''s finding is a sound, checkable cause.", "3": "There is no evidence for this belief."}'),
  ('LR-0456', 'Logical Reasoning', 'Cause and effect', 'Positive reasoning', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.3', 'Littering is a problem in a town. Which message is most likely to build positive action?', '["People in this town are dirty and lazy", "Nothing can ever be done about litter", "Clean streets keep our children healthy, so let''s each keep our own street clean and use the new bins", "Only the government is to blame for the litter"]', 2, 'A positive message gives a good reason and a simple action everyone can take.', '{"0": "Insults make people defensive rather than helpful.", "1": "This discourages any effort.", "3": "Blaming others removes people''s sense that they can help."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0457', 'Logical Reasoning', 'Cause and effect', 'Positive reasoning', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.3', 'A student group''s science project failed on the day of the exhibition. Which response builds the most positive outcome?', '["Give up science projects for good", "Blame one group member in front of everyone", "Pretend the project never happened", "Work out what went wrong and try again with that fixed"]', 3, 'Finding the cause and fixing it turns failure into learning.', '{"0": "Quitting prevents learning from the mistake.", "1": "Public blame harms teamwork and fixes nothing.", "2": "Ignoring a failure means repeating it."}'),
  ('LR-0458', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: The government sharply raised the tax on cigarettes.
Statement II: Cigarette sales fell over the following months.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'A higher tax raises the price, and higher prices reduce how much people buy. So the tax rise (I) caused the fall in sales (II).', '{"1": "Falling sales came after the tax and cannot have caused it.", "2": "The tax rise directly causes the fall; no third event is needed.", "3": "Price and sales are clearly linked."}'),
  ('LR-0459', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Many farmers in the district switched from wheat to vegetables this year.
Statement II: Vegetable prices in the local market fell.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'More farmers growing vegetables means more vegetables in the market, and a bigger supply pushes prices down.', '{"1": "Falling prices would discourage, not cause, a switch to vegetables.", "2": "The switch itself explains the fall in price.", "3": "Supply and price are directly linked."}'),
  ('LR-0460', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Hospital admissions for breathing problems rose in Lahore.
Statement II: Schools in Lahore were closed for a week.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'Both are typical results of severe winter smog: it causes breathing problems and leads authorities to close schools. Neither statement causes the other.', '{"0": "Hospital admissions do not make the government close schools.", "1": "Closing schools does not cause breathing problems.", "3": "Both are linked through the same cause, smog."}'),
  ('LR-0461', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: The price of petrol rose steeply.
Statement II: More people started using the metro bus.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'Costlier petrol makes driving more expensive, so more people switch to cheaper public transport.', '{"1": "More metro riders would not push up petrol prices.", "2": "The petrol price rise itself explains the shift.", "3": "Travel costs affect how people choose to travel."}'),
  ('LR-0462', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Many students at a college fell ill with a stomach infection.
Statement II: The college postponed its exams.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'The college postponed the exams because many students were ill.', '{"1": "Postponing exams does not cause a stomach infection.", "2": "The illness directly led to the postponement.", "3": "The postponement is a response to the illness."}'),
  ('LR-0463', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Sugar prices rose sharply this year.
Statement II: Floods badly damaged this year''s sugarcane crop.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Less sugarcane means less sugar, so the price rises. The crop damage (II) caused the price rise (I).', '{"0": "Higher sugar prices cannot damage crops.", "2": "The flood damage is itself the cause of the price rise.", "3": "Crop supply directly affects sugar prices."}'),
  ('LR-0464', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: The city''s power supply failed for twelve hours.
Statement II: Many shops reported spoiled frozen food.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'Without power, freezers stop working and frozen food spoils. The power failure caused the spoilage.', '{"1": "Spoiled food cannot cause a power failure.", "2": "The power cut is the direct cause.", "3": "Freezers depend on electricity."}'),
  ('LR-0465', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Doctors at government hospitals in the city went on strike.
Statement II: Private clinics in the city were overcrowded.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 0, 'With government doctors on strike, patients went to private clinics instead, crowding them.', '{"1": "Crowded clinics did not cause the strike.", "2": "The strike itself explains the crowding.", "3": "Patients turned to private clinics because of the strike."}'),
  ('LR-0466', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Water levels in the village wells dropped sharply.
Statement II: Because canal water was short, farmers pumped far more groundwater for their crops.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Heavy pumping draws down the groundwater, so the wells fall. The pumping (II) caused the drop (I).', '{"0": "Falling wells did not cause more pumping; the canal shortage did.", "2": "II is itself the direct cause of I.", "3": "Pumping groundwater lowers well water."}'),
  ('LR-0467', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Large numbers of fish died in the river.
Statement II: A factory upstream began releasing untreated waste into the river.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Untreated industrial waste poisons water and can kill fish. II caused I.', '{"0": "Dead fish do not make a factory release waste.", "2": "The waste is itself the cause.", "3": "Pollution and fish deaths are clearly linked."}'),
  ('LR-0468', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Attendance at the college fell sharply.
Statement II: The college stopped its bus service.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Without the bus, many students could not easily reach the college, so attendance fell.', '{"0": "Lower attendance came after the bus service stopped, not before.", "2": "Stopping the bus is the direct cause.", "3": "Transport directly affects attendance."}'),
  ('LR-0469', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Frost damaged wheat and vegetable crops across the district.
Statement II: Household gas use in the district reached a record high.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'A severe cold spell explains both: frost harms crops, and families burn more gas to keep warm. Neither causes the other.', '{"0": "Crop damage does not make households burn more gas.", "1": "Burning gas at home does not cause frost in the fields.", "3": "Both share a common cause, the severe cold."}'),
  ('LR-0470', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Demand for umbrellas rose in the city.
Statement II: Many low-lying streets were flooded.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'Heavy rain explains both: people buy umbrellas and low-lying streets flood.', '{"0": "Buying umbrellas does not flood streets.", "1": "Flooded streets alone do not create a need for umbrellas; the rain does.", "3": "Both follow from heavy rain."}'),
  ('LR-0471', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Many schools announced their winter holidays early.
Statement II: Sales of gas heaters rose.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'An unusually early cold spell explains both: schools close early and people buy heaters.', '{"0": "School holidays do not make people buy heaters.", "1": "Heater sales do not make schools close.", "3": "Both come from the early cold."}'),
  ('LR-0472', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: The college cricket team won the inter-college cup.
Statement II: The price of wheat flour rose in the city.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 3, 'A college cricket win and the price of flour have no causal connection.', '{"0": "A cricket win cannot change flour prices.", "1": "Flour prices do not affect a cricket result.", "2": "No single event would plausibly cause both."}'),
  ('LR-0473', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: A new hospital opened in Multan.
Statement II: Mango exports from Multan rose this year.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 3, 'Opening a hospital has nothing to do with mango exports, and exports do not cause hospitals to open.', '{"0": "A hospital does not boost mango exports.", "1": "Mango exports did not cause the hospital to open.", "2": "No obvious single cause explains both."}'),
  ('LR-0474', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'moderate', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: The national hockey team lost an important match.
Statement II: More students passed the MDCAT this year.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 3, 'These two events are unrelated.', '{"0": "A hockey loss does not affect MDCAT results.", "1": "MDCAT results do not affect a hockey match.", "2": "No single cause explains both."}'),
  ('LR-0475', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Hundreds of travellers were stranded on the road overnight.
Statement II: Heavy snowfall blocked the road near Murree.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'The blocked road is why the travellers were stranded. II caused I.', '{"0": "Stranded travellers do not cause snowfall.", "2": "The snow-blocked road is itself the cause.", "3": "A blocked road strands travellers."}'),
  ('LR-0476', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: The board announced its exam results two weeks late.
Statement II: The board''s computer system was hit by a cyber-attack.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'A cyber-attack on the system used to process results would delay them. II caused I.', '{"0": "A late result does not cause a cyber-attack.", "2": "The attack is itself the direct cause.", "3": "Processing results depends on the computer system."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10, s.column11,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('LR-0477', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Many students in the hostel developed diarrhoea.
Statement II: Several cooks in the hostel kitchen also fell ill with diarrhoea.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 2, 'Both groups ate and drank in the same place, so a shared source such as contaminated food or water most likely made both ill.', '{"0": "It is unlikely that the students infected the cooks; both point to a shared source.", "1": "Sick cooks could spread germs, but cooks and students falling ill together points most strongly to a shared contaminated source.", "3": "Two groups falling ill in the same place with the same illness are very likely linked."}'),
  ('LR-0478', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'The well water in a coastal town has slowly become salty over a few years after decades of tasting fresh. What is the most likely cause?', '["People in the town now eat more salt", "A new road was built through the town", "The town has had more rainfall than usual", "Heavy pumping of groundwater has let seawater seep into the underground water"]', 3, 'In coastal areas, pumping out too much fresh groundwater lets salty seawater move in underground (saltwater intrusion).', '{"0": "What people eat does not change the well water.", "1": "A road does not make groundwater salty.", "2": "More rain would freshen, not salt, the groundwater."}'),
  ('LR-0479', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'A bus crashed at night on a mountain road. Which of these is most likely a CAUSE of the crash rather than an effect?', '["The driver had been driving for 16 hours without rest", "Injured passengers were taken to hospital", "The road was closed for several hours", "The transport department ordered an inquiry"]', 0, 'A tired driver is a common cause of crashes. The other options are things that happened because of the crash.', '{"1": "Taking passengers to hospital is a result of the crash.", "2": "Closing the road is a result of the crash.", "3": "The inquiry is a response to the crash."}'),
  ('LR-0480', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Which is most likely an EFFECT of a long power cut in a village in summer?', '["A transformer was overloaded", "Tube wells that run on electricity stopped supplying water", "A storm damaged the power lines", "Demand for electricity was higher than supply"]', 1, 'Electric tube wells cannot run without power, so water supply stops as a result of the power cut. The other options are possible causes of the cut.', '{"0": "An overloaded transformer is a possible cause of the cut.", "2": "Storm damage is a possible cause of the cut.", "3": "Demand exceeding supply is a possible cause of the cut."}'),
  ('LR-0481', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Investigators of a night-time factory fire found three things: the emergency exits were blocked, the wiring in the storeroom was faulty and sparking, and the storeroom held large bales of cotton.
Which most likely STARTED the fire?', '["The blocked emergency exits", "The bales of cotton", "The faulty, sparking wiring", "The fact that it was night-time"]', 2, 'Sparks from faulty wiring are an ignition source. The cotton was fuel that helped the fire spread, and blocked exits made it more dangerous, but neither started it.', '{"0": "Blocked exits made escape harder; they did not start the fire.", "1": "Cotton burns easily but needs something to ignite it.", "3": "The time of day does not start a fire."}'),
  ('LR-0482', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Heavy rain caused the river to overflow. The flood destroyed crops in the area, and food prices in the nearby town rose.
What is the IMMEDIATE cause of the rise in food prices?', '["The heavy rain", "The river overflowing", "The town being near the river", "The destruction of crops"]', 3, 'Prices rose because less food was available, which was the direct result of the crops being destroyed. The rain and the flood are earlier causes in the chain.', '{"0": "Rain is the starting cause, not the immediate one.", "1": "The flood led to the crop loss, which then raised prices.", "2": "Being near the river is a background condition."}'),
  ('LR-0483', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'Many people believe that more patients come to the emergency room on full-moon nights. A hospital checked two years of its records and found no difference between full-moon nights and other nights.
What is the most reasonable conclusion?', '["The hospital''s evidence does not support the belief", "The full moon causes more emergencies", "The hospital''s records must be wrong", "People who believe it are lying"]', 0, 'Two years of records showing no difference is good evidence against the belief, at least for this hospital.', '{"1": "The records show no such effect.", "2": "There is no reason to doubt the records just because they disagree with a popular belief.", "3": "People can sincerely hold a mistaken belief."}'),
  ('LR-0484', 'Logical Reasoning', 'Cause and effect', 'Rejecting false beliefs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'A man says, "My uncle smoked all his life and lived to 95, so smoking is not harmful."
What is the best reply?', '["Your uncle must not have really smoked", "One person''s case cannot outweigh large studies showing that smokers, on average, live shorter and less healthy lives", "Smoking is harmful only to old people", "People who live to 95 are always healthy"]', 1, 'A single exception does not disprove a pattern found across very large numbers of people.', '{"0": "There is no reason to doubt his story; it simply does not prove the general claim.", "2": "Smoking harms people of all ages.", "3": "This is untrue and irrelevant."}'),
  ('LR-0485', 'Logical Reasoning', 'Cause and effect', 'Positive reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.3', 'Saad did not get the MDCAT score he needed on his first attempt. Which way of thinking is the most constructive?', '["Decide he will never succeed in any exam", "Blame the test as unfair, so there is nothing to learn", "Find out which topics cost him marks and plan focused practice before the next attempt", "Believe that luck alone decides results"]', 2, 'Looking at the causes of the result and acting on them turns a setback into a plan for improvement.', '{"0": "One result does not decide every future attempt.", "1": "Blaming the test leaves no room to improve.", "3": "Preparation clearly affects results."}'),
  ('LR-0486', 'Logical Reasoning', 'Cause and effect', 'Positive reasoning', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.3', 'After a child had a mild fever following a vaccination, some parents in a village decided vaccines are dangerous. Which argument would best build trust in vaccination?', '["Parents who refuse vaccines are foolish", "Vaccines never cause any side effects at all", "The government says so, and that is enough", "A short, mild fever is a common sign that the body is responding, and large studies show vaccines prevent far more illness than they cause"]', 3, 'This argument admits the real but minor side effect, explains it, and gives strong evidence of overall benefit. Honest, evidence-based reasons build trust.', '{"0": "Insulting parents does not persuade them.", "1": "This is untrue; minor side effects are common.", "2": "An appeal to authority alone is weaker than evidence."}'),
  ('LR-0487', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Many families in the city bought water filters.
Statement II: Tests found harmful bacteria in the city''s water supply.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'Learning that the supply carries harmful bacteria leads families to buy filters. II caused I.', '{"0": "Buying filters does not put bacteria in the supply.", "2": "The test result is itself the cause.", "3": "Water quality directly affects whether people buy filters."}'),
  ('LR-0488', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Reported dengue cases fell sharply in October.
Statement II: Night temperatures dropped below 15 °C in October.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'The mosquito that spreads dengue becomes far less active and breeds less in cool weather, so cases fall. II caused I.', '{"0": "Fewer dengue cases cannot lower the temperature.", "2": "The cooler weather is itself the direct cause of fewer cases.", "3": "Temperature strongly affects mosquito activity and dengue spread."}'),
  ('LR-0489', 'Logical Reasoning', 'Cause and effect', 'Cause and effect pairs', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.1', 'Statement I: Shops in the main market stayed closed for a week.
Statement II: Traders in the main market went on strike against a new tax.
What is the relationship between the two statements?', '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', 1, 'The traders'' strike is the reason the shops were closed. II caused I.', '{"0": "Closed shops do not cause a tax protest; the strike came first.", "2": "The strike itself explains the closures.", "3": "A traders'' strike means closed shops."}'),
  ('LR-0490', 'Logical Reasoning', 'Cause and effect', 'Giving reasons for events', 'hard', 'Markhor Prep original question. PMDC MDCAT curriculum 2025, Logical Reasoning learning outcome 5.6.2', 'Data show that towns with more fire engines also suffer more fire damage each year. Which fact best explains this WITHOUT fire engines causing damage?', '["Bigger towns have both more fire engines and more fires", "Fire engines are painted red", "Fire engines use a lot of water", "Some fire engines are old"]', 0, 'Town size is a common cause: large towns have more buildings and more fires, and also need more fire engines. The link between the two is not causal.', '{"1": "Colour is irrelevant.", "2": "Water use does not explain why towns with more engines have more damage.", "3": "Age of engines does not explain the pattern across towns."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT INTO question_counters (prefix, n) VALUES ('LR', 490) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 490);
